-- ============================================================
-- QUIZ DATABASE SCHEMA & DATA
-- System: IC3 / TiH-Spark Quiz Platform
-- Tables: images, categories, levels, questions, minitest_questions,
--         question_options, question_pairs, question_statements
-- ============================================================

-- ── IMAGES (master, edit here to update all references) ───────────────────
CREATE TABLE IF NOT EXISTS images (
    image_id      VARCHAR(20)  PRIMARY KEY,
    filename      VARCHAR(50)  NOT NULL,
    file_path     VARCHAR(200) NOT NULL,
    description   TEXT,
    uploaded_at   TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMP    DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

-- ── CATEGORIES ────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS categories (
    cat_id   VARCHAR(10) PRIMARY KEY,
    name     VARCHAR(60) NOT NULL,
    color    VARCHAR(20)
);

-- ── LEVELS ────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS levels (
    level_id  VARCHAR(10) PRIMARY KEY,
    cat_id    VARCHAR(10) NOT NULL,
    name      VARCHAR(60) NOT NULL,
    grade     VARCHAR(5)  NOT NULL,
    FOREIGN KEY (cat_id) REFERENCES categories(cat_id)
);

-- ── MINITEST_QUESTIONS (one row per question instance) ────────────────────
-- uid format: {cat}__{grade}__{mt#}__q{sort}
-- image_id: auto-matched; set NULL to use SVG placeholder; override anytime
CREATE TABLE IF NOT EXISTS minitest_questions (
    uid           VARCHAR(60)  PRIMARY KEY,
    cat_id        VARCHAR(10)  NOT NULL,
    level_id      VARCHAR(10)  NOT NULL,
    minitest_num  TINYINT      NOT NULL,
    sort_order    INT          NOT NULL,
    question_text TEXT         NOT NULL,
    question_type VARCHAR(20)  NOT NULL,
    image_id      VARCHAR(20),
    has_image     BOOLEAN      DEFAULT FALSE,
    FOREIGN KEY (cat_id)    REFERENCES categories(cat_id),
    FOREIGN KEY (level_id)  REFERENCES levels(level_id),
    FOREIGN KEY (image_id)  REFERENCES images(image_id)
);

-- ── QUESTION_OPTIONS ──────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS question_options (
    id            INT          AUTO_INCREMENT PRIMARY KEY,
    question_uid  VARCHAR(60)  NOT NULL,
    option_text   TEXT         NOT NULL,
    is_correct    BOOLEAN      DEFAULT FALSE,
    sort_order    INT          NOT NULL,
    FOREIGN KEY (question_uid) REFERENCES minitest_questions(uid)
);

-- ── QUESTION_PAIRS (matching) ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS question_pairs (
    id            INT          AUTO_INCREMENT PRIMARY KEY,
    question_uid  VARCHAR(60)  NOT NULL,
    left_text     TEXT         NOT NULL,
    right_text    TEXT         NOT NULL,
    sort_order    INT          NOT NULL,
    FOREIGN KEY (question_uid) REFERENCES minitest_questions(uid)
);

-- ── QUESTION_STATEMENTS (truefalse) ──────────────────────────────────────
CREATE TABLE IF NOT EXISTS question_statements (
    id              INT          AUTO_INCREMENT PRIMARY KEY,
    question_uid    VARCHAR(60)  NOT NULL,
    statement_text  TEXT         NOT NULL,
    correct_answer  BOOLEAN      NOT NULL,
    sort_order      INT          NOT NULL,
    FOREIGN KEY (question_uid) REFERENCES minitest_questions(uid)
);

