-- ============================================================
-- USEFUL QUERIES
-- ============================================================

-- Get all questions for a minitest with image paths
SELECT mq.uid, mq.sort_order, mq.question_text, mq.question_type,
       i.image_id, i.file_path AS image_path, i.description AS image_desc
FROM minitest_questions mq
LEFT JOIN images i ON mq.image_id = i.image_id
WHERE mq.cat_id = 'tih' AND mq.level_id = 'K3' AND mq.minitest_num = 1
ORDER BY mq.sort_order;

-- Update image for a specific question (easy override)
UPDATE minitest_questions SET image_id = 'Picture1' WHERE uid = 'thcs__k6__mt1__q8';

-- Add a new image
VALUES ('Picture90', 'Picture90.png', 'img/Picture90.png', 'Description here');

-- List all questions missing an image
SELECT uid, question_text FROM minitest_questions WHERE image_id IS NULL;

-- Count matched images per grade
SELECT level_id, COUNT(*) total, SUM(has_image) matched,
       ROUND(SUM(has_image)*100/COUNT(*),1) pct
FROM minitest_questions GROUP BY level_id ORDER BY level_id;
