INSERT INTO minitest_questions (uid, cat_id, level_id, minitest_num, sort_order, question_text, question_type, image_id, has_image) VALUES
  ('thcs__k6__mt1__q1', 'thcs', 'K6', 1, 1, 'Bạn nên sử dụng hai phương pháp nào để giảm tình trạng mỏi mắt khi sử dụng màn hình kỹ thuật số? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q2', 'thcs', 'K6', 1, 2, 'Giáo viên hướng dẫn bạn chỉnh sửa bài nghiên cứu của một người bạn cùng lớp. Đâu là hai công cụ bạn nên sử dụng? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q3', 'thcs', 'K6', 1, 3, 'Tương ứng với mỗi Hệ điều hành, bạn hãy chọn Công ty phát triển tương ứng', 'matching', 'Picture56', TRUE),
  ('thcs__k6__mt1__q4', 'thcs', 'K6', 1, 4, 'Ghép từng loại ứng dụng phần mềm với mục đích tương ứng', 'matching', 'Picture18', TRUE),
  ('thcs__k6__mt1__q5', 'thcs', 'K6', 1, 5, 'Giao tiếp không đồng bộ có thể được sử dụng cho những mục đích nào? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q6', 'thcs', 'K6', 1, 6, 'Bạn cần tạo một mật khẩu mạnh. Đâu là ba nguyên tắc bạn cần tuân thủ? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q7', 'thcs', 'K6', 1, 7, 'Bạn đang thực hiện một nghiên cứu trực tuyến. Bạn cần phải điều chỉnh cài đặt tìm kiếm để nhận được kết quả phù hợp hơn với đối tượng nghiên cứu của mình. Đâu là hai kỹ thuật bạn nên sử dụng? (Chọn 2)', 'multi', 'Picture63', TRUE),
  ('thcs__k6__mt1__q8', 'thcs', 'K6', 1, 8, 'Với mỗi câu phát biểu về hệ điều hành Android, hãy chọn Đúng hoặc Sai.', 'truefalse', 'Picture59', TRUE),
  ('thcs__k6__mt1__q9', 'thcs', 'K6', 1, 9, 'Với mỗi câu phát biểu, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q10', 'thcs', 'K6', 1, 10, 'Một bạn nam trong lớp học thiết kế đồ họa đăng tải hình ảnh khuôn mặt của bạn được dán lên mình một con lợn lên trang mạng xã hội. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt1__q11', 'thcs', 'K6', 1, 11, 'Bạn cần xác định thông tin nhận dạng cá nhân (PII) mà bạn không nên để lộ trên mạng. Với mỗi câu phát biểu, hãy chọn Có nếu đó là thông tin nhận dạng cá nhân hoặc Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q12', 'thcs', 'K6', 1, 12, 'Bạn nên sử dụng hai phương pháp nào để ngăn ngừa các chấn thương liên quan đến máy tính? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q13', 'thcs', 'K6', 1, 13, 'Bạn đang viết một bài báo nghiên cứu và đã được hướng dẫn bao gồm các ghi nhận và tài liệu tham khảo. Mục đích của ghi công và tham chiếu là gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt1__q14', 'thcs', 'K6', 1, 14, 'Bạn đang tìm kiếm trên Web để tổng hợp thông tin cho một bài nghiên cứu. Bạn cần xác định các trang Web có khả năng chứa thông tin chính xác và trung lập cho nghiên cứu của bạn. Với mỗi câu phát biểu, hãy chọn Có nếu trang Web đáp ứng được các yêu cầu hoặc Không nếu không thể đáp ứng.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q15', 'thcs', 'K6', 1, 15, 'Đâu là ba yếu tố quan trọng của Chính sách sử dụng được chấp nhận (AUP)? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q16', 'thcs', 'K6', 1, 16, 'Bạn cần lưu danh sách các trang Web để có thể dễ dàng quay trở lại vào lần sau. Bạn nên sử dụng tính năng nào của trình duyệt Web?', 'single', NULL, FALSE),
  ('thcs__k6__mt1__q17', 'thcs', 'K6', 1, 17, 'Với mỗi câu phát biểu về sự khác biệt giữa mạng có dây và không dây, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q18', 'thcs', 'K6', 1, 18, 'Với mỗi câu phát biểu về phần mềm mã nguồn mở, hãy chọn Đúng hoặc Sai:', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q19', 'thcs', 'K6', 1, 19, 'Đối với từng loại hình sử dụng nội dung, hãy chọn Có nếu giấy phép Tài sản sáng tạo công cộng cho phép bạn sử dụng hoặc Không nếu không cho phép.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q20', 'thcs', 'K6', 1, 20, 'Bạn cần xác định các chức năng do Hệ điều hành của máy tính quản lý. Với mỗi tác vụ dưới đây, hãy chọn Đúng nếu đó là tác vụ do Hệ điều hành quản lý và chọn Sai nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q21', 'thcs', 'K6', 1, 21, 'Đâu là hai tác động tiêu cực của việc đăng tải ảnh meme hoặc bình luận xúc phạm lên mạng xã hội? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q22', 'thcs', 'K6', 1, 22, 'Phần mềm gián điệp (Spyware) là gì?', 'single', 'Picture17', TRUE),
  ('thcs__k6__mt1__q23', 'thcs', 'K6', 1, 23, 'Miền công cộng bao gồm tất cả các tác phẩm sáng tạo mà không có quyền sở hữu trí tuệ độc quyền nào được áp dụng. Ba cách nào để một tác phẩm sáng tạo có thể xuất hiện trong miền công cộng? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q24', 'thcs', 'K6', 1, 24, 'Bạn đăng tải một bức ảnh hài hước và đáng xấu hổ của bạn bè lên mạng xã hội. Những thông tin đó sẽ tồn tại trên mạng Internet trong vòng bao lâu?', 'single', NULL, FALSE),
  ('thcs__k6__mt1__q25', 'thcs', 'K6', 1, 25, 'Ghép từng thiết bị lưu trữ dữ liệu với định nghĩa tương ứng:', 'matching', NULL, FALSE),
  ('thcs__k6__mt1__q26', 'thcs', 'K6', 1, 26, 'Bạn đang đưa ra đề xuất, sửa chữa và nhận xét về bài nghiên cứu của một bạn học trong lớp. Bạn đang thực hiện quy trình nào?', 'single', NULL, FALSE),
  ('thcs__k6__mt1__q27', 'thcs', 'K6', 1, 27, 'Khi tham khảo một cuốn sách, những yếu tố nào phải có trong phần trích dẫn (citation)? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q28', 'thcs', 'K6', 1, 28, 'Bạn cần hợp tác với các bạn học và chia sẻ nhật ký lớp học. Nền tảng kỹ thuật số nào thích hợp với hoạt động trong lớp học này? (Chọn 2)', 'multi', 'Picture61', TRUE),
  ('thcs__k6__mt1__q29', 'thcs', 'K6', 1, 29, 'Với mỗi câu phát biểu về những lợi ích của cơ sở hạ tầng mạng chất lượng, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q30', 'thcs', 'K6', 1, 30, 'Đâu là hai hành động bạn có thể thực hiện để giúp duy trì quyền riêng tư kỹ thuật số của bản thân? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q31', 'thcs', 'K6', 1, 31, 'Bạn cần xác định đúng trường địa chỉ email để sử dụng cho các mục đích cụ thể. Ghép từng trường địa chỉ với mục đích tương ứng.', 'matching', NULL, FALSE),
  ('thcs__k6__mt1__q32', 'thcs', 'K6', 1, 32, 'Máy tính để bàn sử dụng phần cứng nào để lưu trữ dữ liệu lâu dài?', 'single', NULL, FALSE),
  ('thcs__k6__mt1__q33', 'thcs', 'K6', 1, 33, 'Với mỗi câu phát biểu về bản quyền, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q34', 'thcs', 'K6', 1, 34, 'Đâu là ba thiết bị cung cấp đầu vào khi được kết nối với máy tính không có màn hình cảm ứng? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q35', 'thcs', 'K6', 1, 35, 'Ghép từng loại cable với tên gọi tương ứng', 'matching', 'Picture38', TRUE),
  ('thcs__k6__mt1__q36', 'thcs', 'K6', 1, 36, 'Bạn cần duy trì bảo mật cho điện thoại thông minh của mình. Đâu là ba nguyên tắc bạn cần tuân thủ? (Chọn 3)', 'multi', 'Picture58', TRUE),
  ('thcs__k6__mt1__q37', 'thcs', 'K6', 1, 37, 'Khi bắt đầu năm học, giáo viên Khoa học sẽ gửi một Email đến tất cả các học sinh trong lớp của bạn. Trong thư có đính kèm một mẫu giấy phép dưới dạng tập tin PDF. Bạn Không có quyền truy cập vào máy in và phải gửi biểu mẫu cho cha mẹ của bạn để in. Trong email của giáo viên, bạn nên sử dụng tùy chọn nào dưới đây để gửi biểu mẫu cho phụ huynh của mình?', 'single', 'Picture29', TRUE),
  ('thcs__k6__mt1__q38', 'thcs', 'K6', 1, 38, 'Với mỗi câu phát biểu, hãy chọn Đúng nếu đó là ví dụ về bắt nạt trên mạng hoặc Sai nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q39', 'thcs', 'K6', 1, 39, 'Đâu là ba yếu tố phải có trong trích dẫn về một cuốn sách đã xuất bản? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q40', 'thcs', 'K6', 1, 40, 'Bạn chụp ảnh kỷ yếu cho trường bằng điện thoại. Bạn chụp hơn 50 bức ảnh mỗi ngày. Bạn cần sử dụng phương pháp nhanh nhất và đáng tin cậy nhất để sao lưu các bức ảnh và xóa chúng khỏi điện thoại mỗi ngày. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt1__q41', 'thcs', 'K6', 1, 41, 'Bạn sử dụng mạng xã hội để giữ liên lạc với bạn bè và gia đình. Bạn đang có kế hoạch đi du lịch vào tháng tới. Đâu là cách an toàn nhất để bạn tự bảo vệ mình khỏi những tên tội phạm trực tuyến khi đăng thông tin về các hoạt động trong kỳ nghi của mình?', 'single', NULL, FALSE),
  ('thcs__k6__mt1__q42', 'thcs', 'K6', 1, 42, 'Bạn cần xác định quy ước đặt tên tập tin nhất quán cho hệ thống quản lý tập tin dùng chung để có thể hỗ trợ nhiều ứng dụng phần mềm và Hệ điều hành. Với mỗi câu phát biểu, hãy chọn Có nếu quy ước đặt tên giúp thực hiện được mục tiêu này hoặc Không nếu không thể.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt1__q43', 'thcs', 'K6', 1, 43, 'Bạn nhập một công thức nấu ăn vào tài liệu Microsoft Word dưới dạng một đoạn văn và chuyển đổi đoạn văn đó thành một danh sách đánh số như trong hình 1. Bạn cần tách đoạn văn thành từng mục danh sách đánh số như trong hình 2. Bạn sử dụng phím hoặc tổ hợp phím nào ở cuối mỗi câu?', 'single', 'Picture46', TRUE),
  ('thcs__k6__mt1__q44', 'thcs', 'K6', 1, 44, 'Các trang web sử dụng hai phương pháp nào để theo dõi thói quen duyệt Web trực tuyến của khách truy cập? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt1__q45', 'thcs', 'K6', 1, 45, 'Để sử dụng ứng dụng, mạng hoặc dịch vụ, bạn có thể phải đồng ý tuân thủ Chính sách sử dụng được chấp nhận. Chính sách sử dụng được chấp nhận đề cập đến hai loại thông tin nào? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q1', 'thcs', 'K6', 2, 1, 'Ghép từng bộ phận phần cứng của máy tính với hình ảnh tương ứng. Để trả lời, hãy di chuyển từng bộ phận từ danh sách ở bên trái sang hình ảnh tương ứng ở bên phải.', 'matching', NULL, FALSE),
  ('thcs__k6__mt2__q2', 'thcs', 'K6', 2, 2, 'Với mỗi câu phát biểu về sự khác biệt giữa Internet và Intranet, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q3', 'thcs', 'K6', 2, 3, 'Bạn tên là Sam Grey. Bạn đang cập nhật dự án của trường và muốn lưu một phiên bản mới. Bạn cần đặt tên cho tập tin sao cho trong đó phải bao gồm tên tác giả, dễ đọc và hỗ trợ khả năng sử dụng trên Web cũng như khả năng tương thích với nhiều nền tảng. Bạn nên sử dụng tên tập tin như thế nào?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q4', 'thcs', 'K6', 2, 4, 'Đối với mỗi phát biểu liên quan đến phần mềm nguồn mở và độc quyền sau, hãy chọn Đúng hoặc Sai cho mỗi phát biểu sau:', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q5', 'thcs', 'K6', 2, 5, 'Bạn đã tải xuống một số bài hát mình yêu thích và sử dụng chúng trong bài thuyết trình mà bạn đã gửi tới Hội chợ Khoa học toàn quốc. Bài thuyết trình của bạn bị từ chối vì các bài hát bạn đã chọn đã vi phạm bản quyền. Ba yếu tố nào được sử dụng để đánh giá sử dụng bản quyền hợp pháp? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q6', 'thcs', 'K6', 2, 6, 'Bạn cần xác định các tính năng tiêu chuẩn của thanh tác vụ trong hệ điều hành Windows. Với mỗi câu phát biểu, hãy chọn Có nếu bạn có thể thực hiện hành động từ thanh tác vụ hoặc chọn Không nếu bạn không thể.', 'truefalse', 'Picture1', TRUE),
  ('thcs__k6__mt2__q7', 'thcs', 'K6', 2, 7, 'Bạn đang biên soạn một nghiên cứu. Bạn thu thập thông tin từ nhiều nguồn khác nhau để đưa vào bài nghiên cứu của mình. Bạn cần đưa tài liệu gốc vào mục Tài liệu tham khảo trong bài viết của bạn. Đâu là hai lý do bạn nên đưa tài liệu gốc vào mục Tài liệu tham khảo? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q8', 'thcs', 'K6', 2, 8, 'Với mỗi loại phần mềm, hãy xác định xem đó là phần mềm nào?', 'matching', NULL, FALSE),
  ('thcs__k6__mt2__q9', 'thcs', 'K6', 2, 9, 'Chọn từng thuật ngữ cộng tác với mô tả tương ứng. Để trả lời, hãy chọn từng thuật ngữ từ danh sách tương ứng mô tả.', 'matching', NULL, FALSE),
  ('thcs__k6__mt2__q10', 'thcs', 'K6', 2, 10, 'Ba phát biểu nào dưới đây đúng với phần mềm nguồn mở? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q11', 'thcs', 'K6', 2, 11, 'Bạn đang thực hiện một dự án nghiên cứu. Bạn tìm thấy một bài báo trực tuyến dài chứa thông tin liên quan đến chủ đề nghiên cứu của bạn. Bạn có thể tìm thấy những thông tin nào trên trang web bằng cách sử dụng tính năng Tìm kiếm của trình duyệt?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q12', 'thcs', 'K6', 2, 12, 'Đâu là hai tình huống giao tiếp bằng phương tiện điện tử thích hợp để sử dụng biểu tượng cảm xúc hoặc từ viết tắt? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q13', 'thcs', 'K6', 2, 13, 'Bạn cần thêm một tác phẩm nghệ thuật vào bài trình bày ma bạn đang làm cho lớp học của mình. Bạn không có thời gian để xin giấy phép sử dụng tác phẩm. Với mỗi câu phát biểu, hãy chọn phát biểu Đúng nếu đó là lý do bạn có thể sử dụng tác phẩm nghệ thuật một cách hợp pháp mà không cần phải xin giấy phép (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q14', 'thcs', 'K6', 2, 14, 'Câu nào thể hiện ngôn ngữ bao hàm?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q15', 'thcs', 'K6', 2, 15, 'Virus máy tính là gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q16', 'thcs', 'K6', 2, 16, 'Bạn cần xác định các công cụ có thể giúp bạn bảo vệ quyền riêng tư kỹ thuật số của mình. Với mỗi câu phát biểu, hãy chọn Có nếu tính năng có thể bảo vệ quyền riêng tư kỹ thuật số và Không nếu không thể.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q17', 'thcs', 'K6', 2, 17, 'Bạn cần đảm bảo an toàn cho mật khẩu của mình. Đâu là ba nguyên tắc bạn cần tuân thủ? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q18', 'thcs', 'K6', 2, 18, 'Các trang web sử dụng hai phương pháp nào để theo dõi thói quen duyệt web trực tuyến của khách truy cập? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q19', 'thcs', 'K6', 2, 19, 'Bạn nên sử dụng hai phương pháp nào để giảm tình trạng mỏi mắt khi sử dụng màn hình kỹ thuật số? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q20', 'thcs', 'K6', 2, 20, 'Điều nào sau đây sẽ là đặc điểm của cơ sở hạ tầng mạng tốt cho trường học?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q21', 'thcs', 'K6', 2, 21, 'Bạn đang cộng tác với các học sinh khác trong một dự án khoa học. Nhóm của bạn sẽ gặp nhau để thảo luận về dự án thông qua ứng dụng hội thảo video của nhà trường. Bạn sẽ đóng vai trò là người chủ trì. Bạn cần đảm bảo rằng mỗi học sinh đều được thảo luận về dự án mà không bị các học sinh khác làm gián đoạn. Mỗi học sinh phải làm gì để đạt được mục tiêu này?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q22', 'thcs', 'K6', 2, 22, 'Bạn đang thực hiện một dự án nghiên cứu và cần xác minh liệu một nguồn thông tin có thuộc phạm vi công cộng hay không. Với mỗi câu phát biểu, hãy chọn Đúng nếu đó là lý do khiến một tác phẩm bản quyền có thể rơi vào phạm vi công cộng và Sai nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q23', 'thcs', 'K6', 2, 23, 'Những thông tin về bạn được lưu trữ trực tuyến được gọi là dấu chân kỹ thuật số. Với mỗi câu phát biểu về dấu chân kỹ thuật số, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q24', 'thcs', 'K6', 2, 24, 'Với mỗi câu phát biểu về nền văn hóa, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q25', 'thcs', 'K6', 2, 25, 'Ghép từng hình ảnh thích hợp với hướng trang tương ứng.', 'matching', NULL, FALSE),
  ('thcs__k6__mt2__q26', 'thcs', 'K6', 2, 26, 'Là một người sử dụng máy tính có đạo đức, trách nhiệm của bạn là phải luôn tuân thủ các quy tắc hành xử đúng mực trên mạng. Bạn cần xác định những ví dụ về cách hành xử đúng mực trên mạng trong môi trường làm việc văn phòng. Với mỗi câu phát biểu, hãy chọn Có nếu đó là ví dụ về cách hành xử đúng mực hoặc Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q27', 'thcs', 'K6', 2, 27, 'Bạn cần xác định mục đích của các công cụ trình duyệt web phổ biến. Để trả lời, hãy ghép tên các nút lệnh bên dưới.', 'matching', NULL, FALSE),
  ('thcs__k6__mt2__q28', 'thcs', 'K6', 2, 28, 'Với mỗi câu phát biểu về quy tắc tạo bài trình bày cơ bản, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q29', 'thcs', 'K6', 2, 29, 'Bạn dự định mua một thiết bị máy tính cầm tay. Thiết bị bị phải có khả năng chạy bằng pin và phải được trang bị bàn phím vật lý tích hợp. Đâu là hai thiết bị đáp ứng được những yêu cầu trên? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q30', 'thcs', 'K6', 2, 30, 'Bạn đang đưa ra đề xuất, sửa chữa và đánh giá về bài nghiên cứu của một người bạn cùng lớp. Bạn đang thực hiện quy trình nào?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q31', 'thcs', 'K6', 2, 31, 'Hai hoạt động nào là ví dụ về bắt nạt trên mạng? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q32', 'thcs', 'K6', 2, 32, 'Bạn đã tìm thấy nội dung có Giấy phép Creative Commons. Đối với từng loại hình sử dụng nội dung, hãy chọn Có nếu Giấy phép Creative Commons cho phép bạn sử dụng nội dung theo cách được liệt kê hoặc Không nếu không được', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q33', 'thcs', 'K6', 2, 33, 'Khi trích dẫn thông tin được xuất bản trên Web, bạn nên bao gồm một tuyên bố truy cập cho biết khi nào và ở đâu trên Web mà bạn đã truy cập thông tin. Bạn nên đưa ba mục nào trong tuyên bố truy xuất trích dẫn của mình? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q34', 'thcs', 'K6', 2, 34, 'Bạn sử dụng máy tính công cộng tại thư viện để check email và số dư tài khoản ngân hàng của mình. Bạn muốn ngăn ngừa những người sử dụng máy tính sau đó truy cập vào email và tài khoản ngân hàng của bạn. Bạn nên hoàn thành hai tác vụ nào trước khi rời khỏi máy tính? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q35', 'thcs', 'K6', 2, 35, 'Với mỗi câu phát biểu về các hình ảnh được bảo vệ bởi giấy phép Tài sản sáng tạo công cộng (Creative Commons licenses) và không thuộc phạm vi công cộng, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q36', 'thcs', 'K6', 2, 36, 'Đâu là câu phát biểu đúng về các ứng dụng dựa trên môi trường web?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q37', 'thcs', 'K6', 2, 37, 'Đâu là lợi ích của việc duyệt web "ở chế độ riêng tư"("in private") hoặc "ẩn danh" ("incognito")?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q38', 'thcs', 'K6', 2, 38, 'Ba cách để chuẩn bị cho một cuộc họp kỹ thuật số chuyên nghiệp là gì? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt2__q39', 'thcs', 'K6', 2, 39, 'Đâu là nhân tố đóng góp chính vào danh tiếng số của bạn?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q40', 'thcs', 'K6', 2, 40, 'Xác định chức năng (Nhập/ Xuất) của các thiết bị sau:', 'matching', NULL, FALSE),
  ('thcs__k6__mt2__q41', 'thcs', 'K6', 2, 41, 'Trời đã về khuya. Bạn cảm thấy khó ngủ và quyết định lướt xem các bài đăng của bạn bè trên mạng xã hội. Một học sinh cùng trường với bạn vừa đăng bài thông báo rằng trường học đã bị phá hoại và giờ học sẽ bị lùi lại hai tiếng vào hôm sau. Bạn cần phải xác định xem liệu thông tin đó có chính xác hay không. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q42', 'thcs', 'K6', 2, 42, 'Bạn và một bạn khác đang cùng thực hiện báo cáo khoa học. Bạn tạo một tài liệu dùng chung và lưu vào đám mây. Bạn dự định lưu vào những thời điểm khác nhau. Đây là hình thức cộng tác gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt2__q43', 'thcs', 'K6', 2, 43, 'Bạn đang tìm kiếm thông tin trên các trang web về cách tự trồng rau. Thao tác tìm kiếm của bạn trả về một số trang kết quả. Bạn cần xác định kết quả nào liên quan đến tìm kiếm của bạn. Với mỗi mô tả về trang web, hãy chọn Có nếu trang web đó liên quan đến tìm kiếm của bạn hoặc Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q44', 'thcs', 'K6', 2, 44, 'Lớp của bạn đang lên kế hoạch cho một chuyến đi thực tế để tham quan khuôn viên của các trường đại học. Giáo viên của bạn lên lịch một buổi hội thảo video cho những người tham gia chuyến đi thông qua một phần mềm hiển thị từng người tham dự trên màn hình như minh họa. Bạn có thể tuân thủ các tiêu chuẩn hành xử kỹ thuật số thích hợp. Với mỗi câu phát biểu, hãy chọn Có nếu đó là cách hành xử kỹ thuật số thích hợp hoặc Không nếu không thích hợp.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt2__q45', 'thcs', 'K6', 2, 45, 'Ghép nối từng khái niệm kết nối mạng với định nghĩa tương tự', 'matching', NULL, FALSE),
  ('thcs__k6__mt3__q1', 'thcs', 'K6', 3, 1, 'Tham khảo hình ảnh bên dưới. Người dùng có thể tìm thấy các tùy chọn kết hợp các tài liệu trong nhóm nào dưới Tab ReView?', 'single', NULL, FALSE),
  ('thcs__k6__mt3__q2', 'thcs', 'K6', 3, 2, 'Làm cách nào để người dùng có thể thiết lập một máy tính làm việc để tránh tốt nhất những chấn thương do căng thẳng lặp đi lặp lại? (Chọn 4)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q3', 'thcs', 'K6', 3, 3, 'Lớp của bạn đang lên kế hoạch cho một chuyến đi thực tế để tham quan khuôn viên của các trường đại học. Giáo viên của bạn lên lịch một buổi hội thảo video. Bạn có thể tuân thủ các tiêu chuẩn hành xử kỹ thuật số thích hợp. Với mỗi câu phát biểu, hãy chọn Có nếu đó là cách hành xử kỹ thuật số thích hợp hoặc Không nếu không thích hợp.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q4', 'thcs', 'K6', 3, 4, 'Bạn cần lưu danh sách các trang Web để có thể dễ dàng quay trở lại vào lần sau. Bạn nên sử dụng tính năng nào của trình duyệt Web?', 'single', NULL, FALSE),
  ('thcs__k6__mt3__q5', 'thcs', 'K6', 3, 5, 'Với mỗi câu phát biểu về quy tắc tạo bài trình bày cơ bản, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q6', 'thcs', 'K6', 3, 6, 'Với mỗi câu phát biểu về hệ điều hành Android, hãy chọn Đúng hoặc Sai.', 'truefalse', 'Picture59', TRUE),
  ('thcs__k6__mt3__q7', 'thcs', 'K6', 3, 7, 'Đối với mỗi tuyên bố về bản quyền, hãy chọn Có nếu bạn có thể sử dụng hợp pháp tác phẩm sáng tạo mà không xin phép hoặc Không nếu bạn không thể.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q8', 'thcs', 'K6', 3, 8, 'Với mỗi câu phát biểu về các phương pháp trích dẫn, hãy chọn Đúng hoặc Sai', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q9', 'thcs', 'K6', 3, 9, 'Các trang web sử dụng hai phương pháp nào để theo dõi thói quen duyệt web trực tuyến của khách truy cập? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q10', 'thcs', 'K6', 3, 10, 'Ghép từng loại ứng dụng phần mềm với mục đích tương ứng:', 'matching', 'Picture18', TRUE),
  ('thcs__k6__mt3__q11', 'thcs', 'K6', 3, 11, 'Điều nào sau đây sẽ là đặc điểm của cơ sở hạ tầng mạng tốt cho trường học?', 'single', NULL, FALSE),
