  ('thcs__k6__mt3__q14', 'thcs', 'K6', 3, 14, 'Các trang web sử dụng hai phương pháp nào để theo dõi thói quen duyệt Web trực tuyến của khách truy cập? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q15', 'thcs', 'K6', 3, 15, 'Giáo viên hướng dẫn bạn chỉnh sửa bài nghiên cứu của một người bạn cùng lớp. Đâu là hai công cụ bạn nên sử dụng? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q16', 'thcs', 'K6', 3, 16, 'Bạn đã tải xuống một số bài hát mình yêu thích và sử dụng chúng trong bài thuyết trình mà bạn đã gửi tới Hội chợ Khoa học toàn quốc. Bài thuyết trình của bạn bị từ chối vì các bài hát bạn đã chọn đã vi phạm bản quyền. Ba yếu tố nào được sử dụng để đánh giá sử dụng bản quyền hợp pháp? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q17', 'thcs', 'K6', 3, 17, 'Bạn cần xác định các tính năng tiêu chuẩn của thanh tác vụ trong hệ điều hành Windows. Với mỗi câu phát biểu, hãy chọn Có nếu bạn có thể thực hiện hành động từ thanh tác vụ hoặc chọn Không nếu bạn không thể.', 'truefalse', 'Picture1', TRUE),
  ('thcs__k6__mt3__q18', 'thcs', 'K6', 3, 18, 'Bạn cần xác định đúng trường địa chỉ email để sử dụng cho các mục đích cụ thể. Ghép từng trường địa chỉ với mục đích tương ứng.', 'matching', NULL, FALSE),
  ('thcs__k6__mt3__q19', 'thcs', 'K6', 3, 19, 'Tham khảo hình ảnh bên dưới. Nếu người dùng chọn tùy chọn Reply, ai sẽ nhận được phản hồi?', 'single', NULL, FALSE),
  ('thcs__k6__mt3__q20', 'thcs', 'K6', 3, 20, 'Đại dịch đã tạm thời đóng cửa trường học của bạn, vì vậy các bài học của bạn đang được giảng dạy trực tuyến. Giáo viên của bạn đã lên lịch các lớp học bằng phần mềm video hiển thị từng học sinh trên màn hình và cho phép học sinh đó nói chuyện với cả lớp. Điều nào sau đây thể hiện nghi thức kỹ thuật số thích hợp cho việc công tác bằng hình ảnh?', 'single', NULL, FALSE),
  ('thcs__k6__mt3__q21', 'thcs', 'K6', 3, 21, 'Với mỗi câu phát biểu về các hình ảnh được bảo vệ bởi giấy phép Tài sản sáng tạo công cộng (Creative Commons licenses) và không thuộc phạm vi công cộng, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q22', 'thcs', 'K6', 3, 22, 'Đối với mỗi phát biểu liên quan đến phần mềm nguồn mở và độc quyền sau, hãy chọn Đúng hoặc Sai cho mỗi phát biểu sau:', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q23', 'thcs', 'K6', 3, 23, 'Với mỗi câu phát biểu về sự khác biệt giữa mạng có dây và không dây, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q24', 'thcs', 'K6', 3, 24, 'Đối với mỗi phát biểu liên quan đến Hệ điều hành trên thiết bị di động, hãy chọn Đúng hoặc Sai với mỗi phát biểu sau:', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q25', 'thcs', 'K6', 3, 25, 'Bạn đang thu thập thông tin trực tuyến cho một bài nghiên cứu. Bạn cần thu thập thông tin về từng nguồn để có thể tạo danh sách tham khảo sau này. Đâu là ba thông tin về mỗi trang web mà bạn cần lưu? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q26', 'thcs', 'K6', 3, 26, 'Bốn điều nào được coi là thông tin nhận dạng cá nhân PII - Personally Identifiable Information? (Chọn 4)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q27', 'thcs', 'K6', 3, 27, 'Bạn chụp rất nhiều ảnh và cần thêm dung lượng lưu trữ. Bạn quyết định mở rộng lưu trữ dữ liệu trên máy tính của mình. Bạn chọn thiết bị lưu trữ nào? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q28', 'thcs', 'K6', 3, 28, 'Khi bắt đầu năm học, giáo viên Khoa học sẽ gửi một Email đến tất cả các học sinh trong lớp của bạn. Trong thư có đính kèm một mẫu giấy phép dưới dạng tập tin PDF. Bạn Không có quyền truy cập vào máy in và phải gửi biểu mẫu cho cha mẹ của bạn để in. Trong email của giáo viên, bạn nên sử dụng tùy chọn nào dưới đây để gửi biểu mẫu cho phụ huynh của mình?', 'single', 'Picture29', TRUE),
  ('thcs__k6__mt3__q29', 'thcs', 'K6', 3, 29, 'Xuân làm dịch vụ chụp ảnh kỷ yếu cho trường trung học bằng điện thoại. Cô chụp hơn 50 bức ảnh mỗi ngày. Xuân cần sử dụng phương pháp nhanh nhất và đáng tin cậy nhất để sao lưu các bức ảnh và xóa chúng khỏi điện thoại mỗi ngày. Xuân nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt3__q30', 'thcs', 'K6', 3, 30, 'Miền công cộng bao gồm tất cả các tác phẩm sáng tạo mà không có quyền sở hữu trí tuệ độc quyền nào được áp dụng. Ba cách nào để một tác phẩm sáng tạo có thể xuất hiện trong miền công cộng? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q31', 'thcs', 'K6', 3, 31, 'Quan sát hình ảnh. Chọn phát biểu Đúng hoặc Sai trong phát biểu dưới đây:', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q32', 'thcs', 'K6', 3, 32, 'Ba cách để chuẩn bị cho một cuộc họp kỹ thuật số chuyên nghiệp là gì? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q33', 'thcs', 'K6', 3, 33, 'Bạn đang biên soạn một nghiên cứu. Bạn cần thêm tài liệu tham khảo cho bài viết của mình. Với mỗi trường hợp, hãy chọn Có nếu bạn phải thêm nguồn tham khảo hoặc Không nếu không cần thiết', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q34', 'thcs', 'K6', 3, 34, 'Bạn đã tìm thấy nội dung có Giấy phép Creative Commons. Đối với từng loại hình sử dụng nội dung, hãy chọn Có nếu Giấy phép Creative Commons cho phép bạn sử dụng nội dung theo cách được liệt kê hoặc Không nếu không được', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q35', 'thcs', 'K6', 3, 35, 'Làm cách nào để người dùng có thể bảo vệ mật khẩu của mình một cách tốt nhất? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q36', 'thcs', 'K6', 3, 36, 'Cách nào hiệu quả nhất để hỏi đồng nghiệp từ xa một câu hỏi đơn giản với mong muốn họ sẽ trả lời nhanh chóng?', 'single', NULL, FALSE),
  ('thcs__k6__mt3__q37', 'thcs', 'K6', 3, 37, 'Chọn từng thuật ngữ cộng tác với mô tả tương ứng. Để trả lời, hãy chọn từng thuật ngữ từ danh sách tương ứng mô tả.', 'matching', NULL, FALSE),
  ('thcs__k6__mt3__q38', 'thcs', 'K6', 3, 38, 'Bạn đang nghiên cứu thông tin trong một tài liệu dài. Với mỗi câu phát biểu, hãy chọn Có nếu bạn có thể sử dụng tính năng Tìm kiếm để hoàn thành công việc hoặc chọn Không nếu bạn không thể.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q39', 'thcs', 'K6', 3, 39, 'Bạn cần xác định các công cụ có thể giúp bạn bảo vệ quyền riêng tư kỹ thuật số của mình. Với mỗi câu phát biểu, hãy chọn Có nếu tính năng có thể bảo vệ quyền riêng tư kỹ thuật số và Không nếu không thể.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q40', 'thcs', 'K6', 3, 40, 'Ba phát biểu nào dưới đây đúng với phần mềm độc quyền? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q41', 'thcs', 'K6', 3, 41, 'Bạn chụp ảnh kỷ yếu cho trường bằng điện thoại. Bạn chụp hơn 50 bức ảnh mỗi ngày. Bạn cần sử dụng phương pháp nhanh nhất và đáng tin cậy nhất để sao lưu các bức ảnh và xóa chúng khỏi điện thoại mỗi ngày. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt3__q42', 'thcs', 'K6', 3, 42, 'Đâu là ba thiết bị xuất khi được kết nối với máy tính không có màn hình cảm ứng? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt3__q43', 'thcs', 'K6', 3, 43, 'Đối với từng loại hình sử dụng nội dung, hãy chọn Có nếu giấy phép Tài sản sáng tạo công cộng cho phép bạn sử dụng hoặc Không nếu không cho phép.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt3__q44', 'thcs', 'K6', 3, 44, 'Rủi ro sức khỏe về tinh thần lớn nhất ở trẻ em và thanh thiếu niên sử dụng công nghệ trực tuyến là gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt3__q45', 'thcs', 'K6', 3, 45, 'Bạn cần hợp tác với các bạn học và chia sẻ nhật ký lớp học. Nền tảng kỹ thuật số nào thích hợp với hoạt động trong lớp học này? (Chọn 2)', 'multi', 'Picture61', TRUE),
  ('thcs__k6__mt4__q1', 'thcs', 'K6', 4, 1, 'Bạn đang thu thập thông tin trực tuyến cho một bài nghiên cứu. Bạn cần thu thập thông tin về từng nguồn để có thể tạo danh sách tham khảo sau này. Đâu là ba thông tin về mỗi trang web mà bạn cần lưu? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q2', 'thcs', 'K6', 4, 2, 'Tham khảo hình ảnh bên dưới. Nếu người dùng chọn tùy chọn Reply, ai sẽ nhận được phản hồi?', 'single', NULL, FALSE),
  ('thcs__k6__mt4__q3', 'thcs', 'K6', 4, 3, 'Đối với từng loại hình sử dụng nội dung, hãy chọn Có nếu giấy phép Tài sản sáng tạo công cộng cho phép bạn sử dụng hoặc Không nếu không cho phép.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q4', 'thcs', 'K6', 4, 4, 'Bạn chụp ảnh kỷ yếu cho trường bằng điện thoại. Bạn chụp hơn 50 bức ảnh mỗi ngày. Bạn cần sử dụng phương pháp nhanh nhất và đáng tin cậy nhất để sao lưu các bức ảnh và xóa chúng khỏi điện thoại mỗi ngày. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt4__q5', 'thcs', 'K6', 4, 5, 'Bạn đang tìm kiếm trên Web để tổng hợp thông tin cho một bài nghiên cứu. Bạn cần xác định các trang Web có khả năng chứa thông tin chính xác và trung lập cho nghiên cứu của bạn. Với mỗi câu phát biểu, hãy chọn Có nếu trang Web đáp ứng được các yêu cầu hoặc Không nếu không thể đáp ứng.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q6', 'thcs', 'K6', 4, 6, 'Với mỗi câu phát biểu về hệ điều hành Android, hãy chọn Đúng hoặc Sai.', 'truefalse', 'Picture59', TRUE),
  ('thcs__k6__mt4__q7', 'thcs', 'K6', 4, 7, 'Với mỗi câu phát biểu về các phương pháp trích dẫn, hãy chọn Đúng hoặc Sai', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q8', 'thcs', 'K6', 4, 8, 'Bạn đang tìm kiếm thông tin trên các trang web về cách tự trồng rau. Thao tác tìm kiếm của bạn trả về một số trang kết quả. Bạn cần xác định kết quả nào liên quan đến tìm kiếm của bạn. Với mỗi mô tả về trang web, hãy chọn Có nếu trang web đó liên quan đến tìm kiếm của bạn hoặc Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q9', 'thcs', 'K6', 4, 9, 'Câu nào thể hiện ngôn ngữ bao hàm?', 'single', NULL, FALSE),
  ('thcs__k6__mt4__q10', 'thcs', 'K6', 4, 10, 'Đâu là hai tác động tiêu cực của việc đăng tải ảnh meme hoặc bình luận xúc phạm lên mạng xã hội? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q11', 'thcs', 'K6', 4, 11, 'Những thông tin về bạn được lưu trữ trực tuyến được gọi là dấu chân kỹ thuật số. Với mỗi câu phát biểu về dấu chân kỹ thuật số, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q12', 'thcs', 'K6', 4, 12, 'Phần mềm gián điệp (Spyware) là gì?', 'single', 'Picture17', TRUE),
  ('thcs__k6__mt4__q13', 'thcs', 'K6', 4, 13, 'Một bạn nam trong lớp học thiết kế đồ họa đăng tải hình ảnh khuôn mặt của bạn được dán lên mình một con lợn lên trang mạng xã hội. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt4__q14', 'thcs', 'K6', 4, 14, 'Đối với mỗi phát biểu liên quan đến Hệ điều hành trên thiết bị di động, hãy chọn Đúng hoặc Sai với mỗi phát biểu sau:', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q15', 'thcs', 'K6', 4, 15, 'Với mỗi câu phát biểu về bản quyền, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q16', 'thcs', 'K6', 4, 16, 'Đâu là hai hành động bạn có thể thực hiện để giúp duy trì quyền riêng tư kỹ thuật số của bản thân? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q17', 'thcs', 'K6', 4, 17, 'Xác định chức năng (Nhập/ Xuất) của các thiết bị sau:', 'matching', NULL, FALSE),
  ('thcs__k6__mt4__q18', 'thcs', 'K6', 4, 18, 'Bạn chụp rất nhiều ảnh và cần thêm dung lượng lưu trữ. Bạn quyết định mở rộng lưu trữ dữ liệu trên máy tính của mình. Bạn chọn thiết bị lưu trữ nào? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q19', 'thcs', 'K6', 4, 19, 'Xuân làm dịch vụ chụp ảnh kỷ yếu cho trường trung học bằng điện thoại. Cô chụp hơn 50 bức ảnh mỗi ngày. Xuân cần sử dụng phương pháp nhanh nhất và đáng tin cậy nhất để sao lưu các bức ảnh và xóa chúng khỏi điện thoại mỗi ngày. Xuân nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt4__q20', 'thcs', 'K6', 4, 20, 'Bạn dự định mua một thiết bị máy tính cầm tay. Thiết bị bị phải có khả năng chạy bằng pin và phải được trang bị bàn phím vật lý tích hợp. Đâu là hai thiết bị đáp ứng được những yêu cầu trên? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q21', 'thcs', 'K6', 4, 21, 'Cách nào hiệu quả nhất để hỏi đồng nghiệp từ xa một câu hỏi đơn giản với mong muốn họ sẽ trả lời nhanh chóng?', 'single', NULL, FALSE),
  ('thcs__k6__mt4__q22', 'thcs', 'K6', 4, 22, 'Ghép từng bộ phận phần cứng của máy tính với hình ảnh tương ứng.', 'matching', NULL, FALSE),
  ('thcs__k6__mt4__q23', 'thcs', 'K6', 4, 23, 'Hai hoạt động nào là ví dụ về bắt nạt trên mạng? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q24', 'thcs', 'K6', 4, 24, 'Bạn đang biên soạn một nghiên cứu. Bạn cần thêm tài liệu tham khảo cho bài viết của mình. Với mỗi trường hợp, hãy chọn Có nếu bạn phải thêm nguồn tham khảo hoặc Không nếu không cần thiết', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q25', 'thcs', 'K6', 4, 25, 'Với mỗi loại phần mềm, hãy xác định xem đó là phần mềm nào?', 'matching', NULL, FALSE),
  ('thcs__k6__mt4__q26', 'thcs', 'K6', 4, 26, 'Ba cách để chuẩn bị cho một cuộc họp kỹ thuật số chuyên nghiệp là gì? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q27', 'thcs', 'K6', 4, 27, 'Tham khảo hình ảnh bên dưới. Người dùng có thể tìm thấy các tùy chọn kết hợp các tài liệu trong nhóm nào dưới Tab ReView?', 'single', NULL, FALSE),
  ('thcs__k6__mt4__q28', 'thcs', 'K6', 4, 28, 'Làm cách nào để người dùng có thể bảo vệ mật khẩu của mình một cách tốt nhất? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q29', 'thcs', 'K6', 4, 29, 'Bạn đang thực hiện một dự án nghiên cứu và cần xác minh liệu một nguồn thông tin có thuộc phạm vi công cộng hay không. Với mỗi câu phát biểu, hãy chọn Đúng nếu đó là lý do khiến một tác phẩm bản quyền có thể rơi vào phạm vi công cộng và Sai nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q30', 'thcs', 'K6', 4, 30, 'Miền công cộng bao gồm tất cả các tác phẩm sáng tạo mà không có quyền sở hữu trí tuệ độc quyền nào được áp dụng. Ba cách nào để một tác phẩm sáng tạo có thể xuất hiện trong miền công cộng? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q31', 'thcs', 'K6', 4, 31, 'Miền công cộng bao gồm tất cả các tác phẩm sáng tạo mà không có quyền sở hữu trí tuệ độc quyền nào được áp dụng. Ba cách nào để một tác phẩm sáng tạo có thể xuất hiện trong miền công cộng? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q32', 'thcs', 'K6', 4, 32, 'Bạn cần xác định quy ước đặt tên tập tin nhất quán cho hệ thống quản lý tập tin dùng chung. Với mỗi câu phát biểu, hãy chọn Có nếu quy ước đặt tên giúp thực hiện được mục tiêu hoặc Không nếu không thể.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q33', 'thcs', 'K6', 4, 33, 'Là một người sử dụng máy tính có đạo đức, trách nhiệm của bạn là phải luôn tuân thủ các quy tắc hành xử đúng mực trên mạng. Bạn cần xác định những ví dụ về cách hành xử đúng mực trên mạng trong môi trường làm việc văn phòng. Với mỗi câu phát biểu, hãy chọn Có nếu đó là ví dụ về cách hành xử đúng mực hoặc Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q34', 'thcs', 'K6', 4, 34, 'Bạn cần xác định mục đích của các công cụ trình duyệt web phổ biến. Để trả lời, hãy ghép tên các nút lệnh bên dưới.', 'matching', NULL, FALSE),
  ('thcs__k6__mt4__q35', 'thcs', 'K6', 4, 35, 'Trời đã về khuya. Bạn cảm thấy khó ngủ và quyết định lướt xem các bài đăng của bạn bè trên mạng xã hội. Một học sinh cùng trường với bạn vừa đăng bài thông báo rằng trường học đã bị phá hoại và giờ học sẽ bị lùi lại hai tiếng vào hôm sau. Bạn cần phải xác định xem liệu thông tin đó có chính xác hay không. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k6__mt4__q36', 'thcs', 'K6', 4, 36, 'Quan sát hình ảnh. Chọn phát biểu Đúng hoặc Sai trong phát biểu dưới đây:', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q37', 'thcs', 'K6', 4, 37, 'Ghép nối từng khái niệm kết nối mạng với định nghĩa tương tự', 'matching', NULL, FALSE),
  ('thcs__k6__mt4__q38', 'thcs', 'K6', 4, 38, 'Ghép từng thiết bị lưu trữ dữ liệu với định nghĩa tương ứng:', 'matching', NULL, FALSE),
  ('thcs__k6__mt4__q39', 'thcs', 'K6', 4, 39, 'Làm cách nào để người dùng có thể thiết lập một máy tính làm việc để tránh tốt nhất những chấn thương do căng thẳng lặp đi lặp lại? (Chọn 4)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q40', 'thcs', 'K6', 4, 40, 'Đối với mỗi phát biểu liên quan đến phần mềm nguồn mở và độc quyền sau, hãy chọn Đúng hoặc Sai:', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q41', 'thcs', 'K6', 4, 41, 'Giáo viên hướng dẫn bạn chỉnh sửa bài nghiên cứu của một người bạn cùng lớp. Đâu là hai công cụ bạn nên sử dụng? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q42', 'thcs', 'K6', 4, 42, 'Ba phát biểu nào dưới đây đúng với phần mềm độc quyền? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k6__mt4__q43', 'thcs', 'K6', 4, 43, 'Đối với mỗi tuyên bố về bản quyền, hãy chọn Có nếu bạn có thể sử dụng hợp pháp tác phẩm sáng tạo mà không xin phép hoặc Không nếu bạn không thể.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q44', 'thcs', 'K6', 4, 44, 'Bạn đang nghiên cứu thông tin trong một tài liệu dài. Với mỗi câu phát biểu, hãy chọn Có nếu bạn có thể sử dụng tính năng Tìm kiếm để hoàn thành công việc hoặc chọn Không nếu bạn không thể.', 'truefalse', NULL, FALSE),
  ('thcs__k6__mt4__q45', 'thcs', 'K6', 4, 45, 'Với mỗi câu phát biểu về phần mềm mã nguồn mở, hãy chọn Đúng hoặc Sai:', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt1__q1', 'thcs', 'K7', 1, 1, 'Với mỗi câu phát biểu về trình duyệt Web, hãy chọn Có nếu bạn có thể thực hiện tác vụ hoặc chọn Không nếu bạn không thể.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt1__q2', 'thcs', 'K7', 1, 2, 'Với mỗi phát biểu sau, hãy chọn Đúng nếu đó là một trong các nguyên tắc Thiết kế Phổ quát (Universal Design), hoặc chọn Sai nếu không phải.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt1__q3', 'thcs', 'K7', 1, 3, 'Xác định ưu điểm của máy in phun và máy in laser. Hãy chọn loại máy in tương ứng với từng ưu điểm. - Tài liệu khô ngay khi in ra. - Thân thiện với môi trường hơn. - Phù hợp để in số lượng ít. - Thích hợp để in tài liệu số lượng lớn với chi phí thấp.', 'matching', 'Picture29', TRUE),
  ('thcs__k7__mt1__q4', 'thcs', 'K7', 1, 4, 'Đặt tên file đúng quy tắc cho file ảnh poster (có nhiều phiên bản):', 'multi', NULL, FALSE),
  ('thcs__k7__mt1__q5', 'thcs', 'K7', 1, 5, 'Với mỗi câu phát biểu về điện toán đám mây, hãy chọn Đúng hoặc Sai: - Các ứng dụng đám mây phải được cập nhật thủ công. - Lưu trữ tập tin trên đám mây kém an toàn hơn so với lưu trữ tập tin cục bộ. - Các ứng dụng và lưu trữ trên đám mây sẽ không có khả năng bị gặp sự cố dịch vụ. - Bạn có thể truy cập các tập tin được lưu trữ trong bộ nhớ đám mây từ bất cứ nơi đâu có kết nối Internet.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt1__q6', 'thcs', 'K7', 1, 6, 'Khi tùy chỉnh điện thoại di động, bạn thường điều chỉnh cài đặt nào dưới đây? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt1__q7', 'thcs', 'K7', 1, 7, 'Khi nhấp vào biểu tượng loa trên thanh tác vụ, chức năng nào sau đây được thực hiện?', 'single', 'Picture1', TRUE),
  ('thcs__k7__mt1__q8', 'thcs', 'K7', 1, 8, 'Tính năng nào trong Excel tự động điền dữ liệu dựa trên mẫu đã có?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q9', 'thcs', 'K7', 1, 9, 'Loại máy in nào phun mực lên giấy khi in?', 'single', 'Picture29', TRUE),
  ('thcs__k7__mt1__q10', 'thcs', 'K7', 1, 10, 'Với mỗi câu phát biểu về bộ xử lý trung tâm (CPU), hãy chọn Đúng hoặc Sai: - Hầu hết các bộ xử lý trung tâm hiện đại đều được xây dựng để hỗ trợ các hệ thống 64-bit. - CPU thường có bộ tản nhiệt khí hoặc tản nhiệt nước đi kèm. - Tốc độ CPU ảnh hưởng đến số khung hình trên giây (fps) hiển thị trong trò chơi 3D.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt1__q11', 'thcs', 'K7', 1, 11, 'Hai điểm khác biệt nào phân biệt giữa máy in Laser và máy in phun? (Chọn 2)', 'multi', 'Picture29', TRUE),
  ('thcs__k7__mt1__q12', 'thcs', 'K7', 1, 12, 'Phần cứng nào trong máy xử lý hiệu suất của video và đồ họa?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q13', 'thcs', 'K7', 1, 13, 'Tính năng nào trong Word tự động sửa lỗi chính tả khi gõ?', 'single', 'Picture2', TRUE),
  ('thcs__k7__mt1__q14', 'thcs', 'K7', 1, 14, 'Cài đặt màn hình nào giúp tăng độ sáng của hình ảnh?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q15', 'thcs', 'K7', 1, 15, 'Nối từng hình thức giao tiếp với tình huống đang sử dụng hình thức đó: - Email - Bài đăng trên diễn đàn điện tử - Bài đăng trên Blog - Tin nhắn văn bản', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q16', 'thcs', 'K7', 1, 16, 'Khi tạo cuộc hẹn hoặc nhiệm vụ trên lịch kỹ thuật số cá nhân, bạn thường có thể tùy chỉnh hai cài đặt nào sau đây? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt1__q17', 'thcs', 'K7', 1, 17, 'Biểu tượng hình mặt trời trên bảng điều khiển thường đại diện cho cài đặt nào?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q18', 'thcs', 'K7', 1, 18, 'Bạn cần chuyển từ tài khoản Google cá nhân sang tài khoản Google trường học. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q19', 'thcs', 'K7', 1, 19, 'Bạn hãy chọn tính năng dùng để chia sẻ toàn bộ lịch với người khác trong Microsoft Outlook Calendar:', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q20', 'thcs', 'K7', 1, 20, 'Hai nguyên tắc thiết kế chung cho phần cứng máy tính là gì? (Chọn 2)', 'multi', NULL, FALSE);
INSERT INTO minitest_questions (uid, cat_id, level_id, minitest_num, sort_order, question_text, question_type, image_id, has_image) VALUES
  ('thcs__k7__mt1__q21', 'thcs', 'K7', 1, 21, 'Bạn đang sử dụng điện thoại Android và muốn giảm độ sáng để tiết kiệm pin. Tính năng nào sau đây cho phép bạn điều chỉnh độ sáng? (Chọn 1)', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q22', 'thcs', 'K7', 1, 22, 'Tùy chọn nào sau đây là phát biểu đúng về quyền đối với tập tin tài liệu? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt1__q23', 'thcs', 'K7', 1, 23, 'Thiết bị xuất nào sau đây được sử dụng để điều khiển âm thanh?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q24', 'thcs', 'K7', 1, 24, 'Các nhà cung cấp bán nhiều hàng hóa và dịch vụ trực tuyến. Tùy chọn nào sau đây là dịch vụ? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt1__q25', 'thcs', 'K7', 1, 25, 'Ghép nguyên tắc thiết kế với định nghĩa đúng: - Liên kết với Internet Vạn vật - Kích thước và không gian để tiếp cận và sử dụng - Sử dụng công bằng - Dễ làm sạch', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q26', 'thcs', 'K7', 1, 26, 'Bạn cần thêm cuộc họp Hội đồng sinh viên vào lịch. Bạn có thể lựa chọn hai phần tử nào sau đây để mở hộp thoại tạo sự kiện? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt1__q27', 'thcs', 'K7', 1, 27, 'Bạn viết một bài luận. Một người bạn cùng lớp nhận xét bài luận này và gợi ý sửa chữa như hình. Bạn cần thực hiện các sửa chữa vĩnh viễn trong tài liệu của mình. Bạn nên sử dụng nút nào?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q28', 'thcs', 'K7', 1, 28, 'Sắp xếp các bước tạo bảng điểm trò chơi trong trang tính theo đúng thứ tự. Ghép mỗi Vị trí (Bước 1→4) với nội dung tương ứng:', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q29', 'thcs', 'K7', 1, 29, 'Bạn đang thêm ngày sinh của bố mình vào lịch cá nhân. Hãy nối từng tùy chỉnh với cài đặt sự kiện tương ứng: 1. Xóa thời gian bắt đầu và kết thúc sự kiện. 2. Thêm sự kiện vào lịch của bạn vào một ngày cố định hằng năm. 3. Nhận thông báo một tuần trước sự kiện. 4. Thêm sự kiện vào lịch của anh trai bạn.', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q30', 'thcs', 'K7', 1, 30, 'Phương pháp nào được sử dụng để chuyển đổi dữ liệu thành định dạng không thể đọc được để bảo vệ thông tin?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q31', 'thcs', 'K7', 1, 31, 'Với mỗi câu phát biểu về tính bảo mật của thiết bị đa phương tiện di động, hãy chọn Đúng hoặc Sai: - Bạn nên tắt tính năng Tự động chạy và Tự động phát cho tất cả các thiết bị đa phương tiện di động. - Bạn nên lưu trữ các công việc và tập tin cá nhân của mình trên các thiết bị riêng biệt, không được cắm thiết bị cá nhân vào máy tính làm việc hoặc ngược lại. - Nếu bạn tìm thấy một thiết bị lưu trữ phương tiện truyền thông và không biết nó thuộc về ai, hãy cắm thiết bị đó vào máy tính của bạn để t', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt1__q32', 'thcs', 'K7', 1, 32, 'Với mỗi câu phát biểu về cáp kết nối, hãy chọn Đúng hoặc Sai: - Bạn có thể sử dụng cáp HDMI để kết nối máy tính xách tay với máy chiếu. - Bạn có thể sử dụng cáp DVI để kết nối trực tiếp hai máy tính nhằm chia sẻ tập tin. - Bạn có thể sử dụng cáp CAT6 Ethernet để kết nối trực tiếp máy tính với bộ định tuyến không dây.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt1__q33', 'thcs', 'K7', 1, 33, 'Ghép từng bên tham gia thanh toán kỹ thuật số với định nghĩa tương ứng: 1. Cho phép các giao dịch 2. Bán hàng hóa và dịch vụ 3. Cung cấp thẻ ghi nợ hoặc thẻ tín dụng', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q34', 'thcs', 'K7', 1, 34, 'Với mỗi câu phát biểu về hệ thống lưu trữ dữ liệu trung tâm, hãy chọn Đúng hoặc Sai: - Khi bạn tải một tập tin lên hệ thống lưu trữ dữ liệu trung tâm, tập tin sẽ bị xóa khỏi máy tính của bạn. - Bạn có thể sử dụng chương trình FTP để tải lên và tải xuống các tập tin từ hệ thống lưu trữ dữ liệu trung tâm. - Nhiều hệ thống lưu trữ dữ liệu trung tâm có thể tự động sao lưu các tập tin từ máy tính và cập nhật phiên bản tập tin mới nhất cho máy tính của bạn.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt1__q35', 'thcs', 'K7', 1, 35, 'Lợi thế của việc sử dụng ví điện tử như Apple Pay hoặc Google Pay là gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q36', 'thcs', 'K7', 1, 36, 'Ghép từng loại tập tin với phần mở rộng phù hợp: - Logo có nền trong suốt - Tập tin chứa các văn bản chưa định dạng - Ảnh mà bạn sẽ hiển thị trên trang Web - Tập tin mà bạn sẽ gửi qua Email cho công ty in', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q37', 'thcs', 'K7', 1, 37, 'Phát biểu nào sau đây giúp phân biệt giữa tập tin chỉ đọc (Read-only) và tập tin đọc-ghi (Read-Write)? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt1__q38', 'thcs', 'K7', 1, 38, 'Bạn nên tắt tinh năng nào trên thiết bị Windows để ngăn phương tiện di động tự động khởi động khi được kết nối với thiết bị? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt1__q39', 'thcs', 'K7', 1, 39, 'Khớp từng cáp với thiết bị mà nó thường kết nối: - Thiết bị chuyển mạch (Switch) - Loa (Speakers) - Bàn phím (Keyboard) - Truyền hình (Television)', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q40', 'thcs', 'K7', 1, 40, 'Cài đặt màn hình nào điều chỉnh sự khác biệt giữa màu sáng và màu tối?', 'single', NULL, FALSE),
  ('thcs__k7__mt1__q41', 'thcs', 'K7', 1, 41, 'Khi khắc phục sự cố máy in không in được, bạn nên thực hiện những bước nào? (Chọn 2)', 'multi', 'Picture29', TRUE),
  ('thcs__k7__mt1__q42', 'thcs', 'K7', 1, 42, 'Khi mô tả Điện toán đám mây, điều nào sau đây sẽ được coi là ưu điểm? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k7__mt1__q43', 'thcs', 'K7', 1, 43, 'Với mỗi câu phát biểu về khắc phục sự cố máy in, hãy chọn Đúng hoặc Sai: - Với máy in được kết nối trực tiếp, hãy thay thế cáp kết nối bằng cáp CAT6. - Kiểm tra trạng thái kết nối máy in trong cửa sổ cài đặt Máy in & Máy quét. - Đối với máy in được kết nối Ethernet, hãy đảm bảo rằng cáp Ethernet được kết nối trực tiếp với máy tính thay vì thông qua bộ chuyển đổi hoặc bộ định tuyến.', 'truefalse', 'Picture29', TRUE),
  ('thcs__k7__mt1__q44', 'thcs', 'K7', 1, 44, 'Với mỗi câu phát biểu về định dạng tập tin, hãy chọn Đúng hoặc Sai: - Các tập tin .txt vẫn giữ nguyên định dạng khi được sao chép từ tập tin khác. - Hình ảnh động có phần mở rộng tập tin .jpg. - Các tập tin có phần mở rộng .pdf trông giống hệt như tập tin gốc nhưng không thể chỉnh sửa được. - Phần mở rộng tập tin hình ảnh có nền trong suốt sẽ là .png', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt1__q45', 'thcs', 'K7', 1, 45, 'Ghép từng mô tả định dạng tập tin với phần mở rộng tương ứng: - Tập tin văn bản hỗ trợ văn bản và đồ họa được định dạng - Tập tin hình vách quét có độ nén cao hỗ trợ chứa nhiều hình ảnh trong một tập tin - Tập tin văn bản chỉ hỗ trợ văn bản thuần - Tập tin hình vách quét với tính năng nén không mất dữ liệu, hỗ trợ hình ảnh trong suốt', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q46', 'thcs', 'K7', 1, 46, 'Các nhà cung cấp thương mại điện tử bán nhiều hàng hóa và dịch vụ khác nhau trên mạng. Phân loại từng mục là', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q47', 'thcs', 'K7', 1, 47, 'Tính năng nào tự động sửa lỗi chính tả khi nhập? Ví dụ: thay ''see you latet'' bằng ''see you later''', 'single', 'Picture2', TRUE),
  ('thcs__k7__mt1__q48', 'thcs', 'K7', 1, 48, 'Tính năng nào trong bảng tính tự động điền nội dung dựa trên dữ liệu hiện có?', 'single', 'Picture57', TRUE),
  ('thcs__k7__mt1__q49', 'thcs', 'K7', 1, 49, 'Ghép từng quyền tập tin với định nghĩa tương ứng: - Xem nội dung tập tin, thêm dữ liệu vào tập tin và xóa tập tin - Thêm dữ liệu vào tập tin và đọc hoặc thay đổi các thuộc tính của tập tin - Xem hoặc truy cập nội dung tập tin và chạy tập tin nếu đó là một chương trình - Xem hoặc truy cập nội dung tập tin', 'matching', NULL, FALSE),
  ('thcs__k7__mt1__q50', 'thcs', 'K7', 1, 50, 'Với mỗi câu phát biểu về mã hóa tập tin, hãy chọn Đúng hoặc Sai: - Mã hóa tập tin làm giảm tốc độ truy cập tập tin. - Tất cả các tập tin trong bộ nhớ đám mây được mã hóa mặc định. - Bạn chỉ có thể mở tập tin được mã hóa trên máy tính đã mã hóa tập tin đó.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q1', 'thcs', 'K7', 2, 1, 'Khép dịch vụ truyền thông trực tuyến với ví dụ của nó: - Thiết bị phát trực tuyến (Streaming Devices) - Trình phát đa phương tiện (Media Players) - Truyền trực tuyến phim (Streaming Movies)', 'matching', NULL, FALSE),
  ('thcs__k7__mt2__q2', 'thcs', 'K7', 2, 2, 'Đối với mỗi phát biểu sau đây, hãy chọn Đúng nếu nó hiện thị mức độ nhạy cảm với sự đa dạng văn hóa hoặc Sai nếu không: - Chú ý đến những định kiến và thành kiến của chính bạn - Đặt câu hỏi thay vì đưa ra giả định - Mua một bộ quần áo thiêng liêng được mặc bởi một nền văn hóa khác và mặc nó để thể hiện rằng bạn muốn trở thành bạn của nhau - Đăng nhiều câu chuyện về một nền văn hóa khác trên các trang mạng xã hội của bạn', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q3', 'thcs', 'K7', 2, 3, 'Sắp xếp các thuật ngữ phải phù hợp theo định nghĩa tương ứng: 1. Độc quyền tạo, sử dụng hoặc bán một sáng chế cụ thể 2. Độc quyền đối với các tác phẩm gốc 3. Độc quyền sử dụng một tác phẩm cụ thể có liên quan đến hàng hóa hoặc dịch vụ trong thương mại', 'matching', NULL, FALSE),
  ('thcs__k7__mt2__q4', 'thcs', 'K7', 2, 4, 'Đâu là hai cách mà học sinh có thể cải thiện khả năng sử dụng các tính năng được phân công? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q5', 'thcs', 'K7', 2, 5, 'Bạn đang nộp đơn xin việc trong lĩnh vực nghề nghiệp đã chọn. Nhà tuyển dụng tiềm năng sẽ truy cập hồ sơ công việc trực tuyến của bạn. Bạn cần làm gì để hỗ trợ hồ sơ công việc trực tuyến của mình?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q6', 'thcs', 'K7', 2, 6, 'Bạn cần xác định xem một bài báo trình bày thông tin theo hướng thiên vị. Đâu là hai dấu hiệu cho thấy bài báo trình bày có thiên vị? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q7', 'thcs', 'K7', 2, 7, 'Ai đó trên trang mạng xã hội yêu thích của bạn vừa đăng thông tin không chính xác về một sự kiện lịch sử của Mỹ. Hai câu trả lời nào tuân theo Netiquette kỹ thuật số? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q8', 'thcs', 'K7', 2, 8, 'Khi sử dụng công cụ tìm kiếm và kết quả được tạo ra từ một tìm kiếm, những danh mục nào có thể được sử dụng để lọc các tìm kiếm? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q9', 'thcs', 'K7', 2, 9, 'Điều nào sau đây là đúng khi chuẩn bị cho hội thảo video? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q10', 'thcs', 'K7', 2, 10, 'Với mỗi câu phát biểu về hành vi trong cộng đồng trực tuyến, hãy chọn Đúng hoặc Sai: - Hy vọng các thành viên khác trong cộng đồng coi thông tin cậu ấy chia sẻ là riêng tư. - Giới thiệu bản thân với các thành viên cộng đồng và cung cấp địa chỉ email cá nhân của cậu ấy. - Trả lời bình luận trên một chuỗi chủ đề nói rằng mình không đồng ý, sử dụng giọng điệu tôn trọng. - Chia sẻ bình luận từ cộng đồng với một nhóm khác mà không nói rõ ai đã đưa ra bình luận đó.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q11', 'thcs', 'K7', 2, 11, 'Công cụ chỉnh sửa hình ảnh nào được dùng để cắt bỏ những phần không mong muốn?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q12', 'thcs', 'K7', 2, 12, 'Bạn lãnh đạo một nhóm gồm những người thuộc các nền văn hóa, giới tính và độ tuổi khác nhau. Bạn dự định tổ chức một cuộc họp từ xa bằng công cụ hội thảo video. Bạn nên thực hiện hai hành động nào sau đây? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q13', 'thcs', 'K7', 2, 13, 'Bạn muốn cập nhật những tiến bộ công nghệ. Hai hành động nào có nhiều khả năng khiến bạn biết đến những tiến bộ công nghệ? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q14', 'thcs', 'K7', 2, 14, 'Hai nhận định nào là đúng về một người nhạy cảm với sự đa dạng văn hóa? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q15', 'thcs', 'K7', 2, 15, 'Với mỗi câu phát biểu về tham gia học online qua hội thảo video, hãy chọn Đúng hoặc Sai: - Bật webcam và tập trung vào màn hình của bạn để người nói, bạn cùng lớp và giáo viên của bạn có thể thấy rằng bạn đang chú ý. - Sử dụng biểu tượng ''Giơ tay'' khi thích hợp để đặt câu hỏi. - Tắt tiếng micrô của bạn và chỉ bật tiếng khi bạn được gọi để thảo luận. - Luôn bật tiếng micrô của bạn để hướng dẫn viên có thể nghe thấy phản ứng của bạn với những gì họ đang nói.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q16', 'thcs', 'K7', 2, 16, 'Trong số các nguồn thông tin trực tuyến, loại trang Web nào có nhiều khả năng xuất bản thông tin đáng tin cậy nhất?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q17', 'thcs', 'K7', 2, 17, 'Hai hành động nào giúp cải thiện thiết kế trang web dựa trên phản hồi của người dùng? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q18', 'thcs', 'K7', 2, 18, 'Bạn có hai tài khoản Microsoft: tài khoản gia đình và tài khoản chơi game. Làm thế nào để chuyển đổi giữa hai tài khoản?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q19', 'thcs', 'K7', 2, 19, 'Bạn quay được video của bạn bè nhảy và muốn chia sẻ video với các bạn cùng lớp. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q20', 'thcs', 'K7', 2, 20, 'Bạn là biên tập viên của một tạp chí trực tuyến về trượt tuyết và muốn biết loại nội dung nào độc giả thích. Bạn nên hỏi những câu hỏi nào? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q21', 'thcs', 'K7', 2, 21, 'Với mỗi phản hồi về bài đăng chứa thông tin y tế không chính xác, hãy chọn Có nếu đó là phản hồi phù hợp, Không nếu không phù hợp:', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q22', 'thcs', 'K7', 2, 22, 'Phát biểu nào sau đây là đúng: ''Nhiều tài nguyên công cộng (Community Resource) có thể được truy cập trực tuyến.''?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q23', 'thcs', 'K7', 2, 23, 'Hai tài nguyên nào có thể chỉ cho bạn cách sử dụng một tính năng trong chương trình phần mềm? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q24', 'thcs', 'K7', 2, 24, 'Bạn là giáo viên và cần gửi email thông báo đến tất cả phụ huynh mà không tiết lộ địa chỉ email của họ với nhau. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q25', 'thcs', 'K7', 2, 25, 'Công ty của bạn muốn khảo sát khách hàng về chiếc xe chạy bằng điện. Với mỗi câu hỏi, hãy chọn Có nếu câu hỏi này mang đến phản hồi hữu ích hoặc Không nếu không: - Bạn có thích phương tiện này không? - Điều gì có thể cải thiện phương tiện này? - Các tính năng quan trọng nhất của xe là gì? - Bạn có muốn giới thiệu phương tiện đi lại này cho một người bạn không?', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q26', 'thcs', 'K7', 2, 26, 'Thời gian tối đa được coi là thời gian cần thiết để trả lời Email trong một môi trường chuyên nghiệp là bao nhiêu?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q27', 'thcs', 'K7', 2, 27, 'Ghép từng thuật ngữ trong bài trình bày với định nghĩa tương ứng: 1. Trang trình bày kiểm soát thiết kế của bạn 2. Hiệu ứng đặc biệt được sử dụng để chuyển tiếp trang trình bày 3. Hiệu ứng hình ảnh có chức năng di chuyển ảnh ra và vào các trang trình bày 4. Tập tin chứa các kiểu tạo sẵn', 'matching', NULL, FALSE),
  ('thcs__k7__mt2__q28', 'thcs', 'K7', 2, 28, 'Ghép nối từng tình huống ở bên phải với từng phương thức giao tiếp ở bên trái sao cho phù hợp nhất: 1. Đặt câu hỏi cho một nhóm để thảo luận về trò chơi. 2. Cho anh của bạn biết nơi sẽ đón bạn. 3. Yêu cầu hoàn lại tiền từ một công ty. 4. Chia sẻ suy nghĩ riêng tư của bạn về sự kiện ẩn vào nhật ký trực tuyến.', 'matching', NULL, FALSE),
  ('thcs__k7__mt2__q29', 'thcs', 'K7', 2, 29, 'Bạn cần chuẩn bị và thực hành thuyết trình bài trình chiếu. Bạn nên làm gì? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q30', 'thcs', 'K7', 2, 30, 'Xác định các trường của một Email. Hãy chuyển từng trường bên phải sang chức năng của nó ở bên trái: 1. Danh sách những người nhận được biết khác 2. Gửi bản sao đến những người nhận ẩn danh khác 3. Các đánh dấu mức độ quan trọng của thư 4. Phần nội dung Email 5. Chủ đề của Email', 'matching', NULL, FALSE),
  ('thcs__k7__mt2__q31', 'thcs', 'K7', 2, 31, 'Hai phát biểu nào là đúng về nguyên tắc nghi thức Email? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q32', 'thcs', 'K7', 2, 32, 'Xác định hai cách để phân biệt danh tính kỹ thuật số cá nhân của bạn với danh tính kỹ thuật số nghề nghiệp của bạn? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q33', 'thcs', 'K7', 2, 33, 'Với mỗi câu phát biểu, hãy chọn Có nếu đó có thể là một phần phản hồi của bạn với bài đăng nói trên là phù hợp hoặc Không nếu không phải: - ''XÓA NGAY ĐI'' - ''Mình hay đăng ảnh đang xấu hổ của bạn'' - ''Làm ơn đừng đăng hình của mình khi chưa có ý kiến''', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q34', 'thcs', 'K7', 2, 34, 'Bạn hãy cho biết ba tài nguyên công cộng (Community Resource) cho phép người dùng tra cứu các tài nguyên trực tuyến? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q35', 'thcs', 'K7', 2, 35, 'Lý do chính để lấy chứng chỉ IT là gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q36', 'thcs', 'K7', 2, 36, 'Nối từng định nghĩa chuỗi tìm kiếm Boolean với chuỗi tìm kiếm Boolean tương ứng: 1. Trả kết quả cho một trong hai hoặc cả hai từ 2. Trả kết quả không bao gồm một từ 3. Trả kết quả cho một trong hai từ', 'matching', NULL, FALSE),
  ('thcs__k7__mt2__q37', 'thcs', 'K7', 2, 37, 'Để thu hẹp kết quả trong tìm kiếm của Google, bạn quyết định sử dụng các cụm từ và ký hiệu cho từ khóa tìm kiếm. Khớp từng từ khóa tìm kiếm với kết quả của nó: 1. Buộc Google tìm kiếm các từ hoặc cụm từ chính xác được đề cập trong dấu ngoặc kép. 2. Sử dụng toán tử này trong tìm kiếm trên Google giữa hai từ khóa sẽ trả về một hoặc cả hai từ khóa trong kết quả. 3. Tìm kiếm từ đồng nghĩa. 4. Đại diện cho toán tử phạm vi để tìm tất cả các kết quả có liên quan trong phạm vi được chỉ định.', 'matching', NULL, FALSE),
  ('thcs__k7__mt2__q38', 'thcs', 'K7', 2, 38, 'Hai tùy chọn nào sau đây giải thích hệ thống lưu trữ dữ liệu trung tâm? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q39', 'thcs', 'K7', 2, 39, 'Bạn có video khoa học muốn chia sẻ với các bạn cùng lớp. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q40', 'thcs', 'K7', 2, 40, 'Giấy phép Creative Commons nào cho phép sử dụng tác phẩm gốc nhưng mà không có sự cho phép của chủ sở hữu?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q41', 'thcs', 'K7', 2, 41, 'Hai tài nguyên nào là tài nguyên cộng đồng có thể dạy bạn sử dụng một tính năng trong chương trình phần mềm? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q42', 'thcs', 'K7', 2, 42, 'Mục đích của trường Bcc trong Email là gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt2__q43', 'thcs', 'K7', 2, 43, 'Hai phương thức giao tiếp nào không đồng bộ? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q44', 'thcs', 'K7', 2, 44, 'Bạn đang tiến hành nghiên cứu bằng cách sử dụng công cụ tìm kiếm. Với mỗi phát biểu về việc sử dụng ''từ Khóa'', hãy chọn Đúng nếu nó hiển thị kết quả hợp lý hoặc Sai nếu không: - ''mustang, camero, -convertible'': Các cụm từ tìm kiếm chính này sẽ trả về tất cả mustang và camero không phải là loại mui trần. - ''Ngựa OR bò OR lợn OR cừu'': Các cụm từ tìm kiếm chính này sẽ trả về kết quả có chứa cả ngựa, bò, lợn hoặc chỉ có cừu. - ''"richest people in America"'': Các cụm từ tìm kiếm quan trọng này', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q45', 'thcs', 'K7', 2, 45, 'Bạn đang sử dụng các tài khoản mạng xã hội cho mục đích cá nhân và công việc. Bạn nên đăng tải hai nội dung nào lên tài khoản mạng xã hội dùng vào mục đích công việc của mình? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q46', 'thcs', 'K7', 2, 46, 'Xem email sau đây - lỗi nào trong email này vi phạm nguyên tắc nghi thức email? (Xem hình) ''Kính gửi bà Smith, Tôi bị bận vào giờ phỏng vấn rồi, chắc là phải đổi lịch thì HY VỌNG ĐIỀU... Cảm ơn nhé!!!''', 'multi', NULL, FALSE),
  ('thcs__k7__mt2__q47', 'thcs', 'K7', 2, 47, 'Với mỗi câu phát biểu về thiết bị được phép sử dụng tại nơi làm việc, hãy chọn Đúng hoặc Sai: - Là thiết bị truyền thông đáng tin cậy. - Một ổ USB nhỏ bạn mang theo từ nhà. - Một ổ USB được công ty cung cấp cho bạn để không bao giờ rời khỏi cơ sở. - Máy tính bảng cá nhân của bạn.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q48', 'thcs', 'K7', 2, 48, 'Với mỗi yếu tố, hãy chọn Có nếu bạn phải xem xét yếu tố đó để đánh giá độ tin cậy hay Không nếu không: - Mức độ phổ biến của nghiên cứu. - Tổ chức tài trợ cho nghiên cứu. - Đơn vị công bố kết quả nghiên cứu.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt2__q49', 'thcs', 'K7', 2, 49, 'Nối từng kiểu mua hàng trong ứng dụng với mô tả tương ứng: 1. Không tự động gia hạn 2. Vật tư tiêu hao 3. Vật tư không tiêu hao 4. Tự động gia hạn', 'matching', NULL, FALSE),
  ('thcs__k7__mt2__q50', 'thcs', 'K7', 2, 50, 'Bạn tạo và điền vào tài liệu một trang, sau đó thêm một trang trống vào tài liệu đó. Bạn cần sao chép tất cả nội dung của trang đầu tiên lên trang thứ hai. Bạn nên sử dụng ba phím tắt nào?', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q1', 'thcs', 'K7', 3, 1, 'Đâu là hai ảnh hưởng của hội chứng FOMO (sợ bỏ lỡ)? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q2', 'thcs', 'K7', 3, 2, 'Với mỗi câu phát biểu về Macro trong một trang tính Excel, hãy chọn Đúng hoặc Sai: - Mỗi Macro được lưu trữ thành một tập tin văn bản. - Bạn có thể tạo ra Macro bằng cách viết lệnh trong trình soạn thảo lệnh. - Macro là chuỗi sự kiện có thể được phát lại, giúp thực hiện các tác vụ lặp lại. - Bạn có thể tạo một Macro bằng cách ghi lại một loạt lệnh, nhấn phím và bấm chuột.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q3', 'thcs', 'K7', 3, 3, 'Hành vi nào sau đây mô tả việc ai đó giả mạo danh tính trực tuyến để lừa đảo người khác?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q4', 'thcs', 'K7', 3, 4, 'Với mỗi câu phát biểu về thanh toán kỹ thuật số, hãy chọn Đúng hoặc Sai: - Tiền mặt có thể được coi là một loại hình thanh toán kỹ thuật số. - Thẻ ghi nợ, thẻ tín dụng, thanh toán chuyển khoản qua ngân hàng và ví điện tử đều là các loại thanh toán kỹ thuật số. - Thanh toán kỹ thuật số diễn ra khi cả người thanh toán và người được thanh toán sử dụng các phương tiện điện tử để thực hiện và nhận thanh toán.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q5', 'thcs', 'K7', 3, 5, 'Với mỗi câu phát biểu về tính bảo mật của webcam, hãy chọn Đúng hoặc Sai: - Mọi người nên che webcam của mình khi không sử dụng. - Tất cả các webcam đều có đèn ghi mà không thể tắt được thông qua phần mềm. - Tắt webcam trong cài đặt máy tính của bạn sẽ bảo vệ bạn khỏi nguy cơ truy cập trái phép.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q6', 'thcs', 'K7', 3, 6, 'Với mỗi câu phát biểu về sức khỏe kỹ thuật số, hãy chọn Đúng hoặc Sai: - Để tránh mỏi mắt, bạn nên chớp mắt thường xuyên theo quy tắc ''20-20-20''. - Để giúp tránh rối loạn giấc ngủ, trước khi đi ngủ, hãy sạc điện thoại ở nơi bạn không thể tiếp cận nhưng vẫn có thể nghe thấy. - Để tránh nghiện mạng xã hội, bạn nên nghỉ ngơi khi duyệt 3-5 trang mạng xã hội. - Để chống lại tình trạng lười vận động, hãy mua một chiếc đồng hồ thể dục để đeo đến trường.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q7', 'thcs', 'K7', 3, 7, 'Dấu hiệu nào cho thấy người bạn quen online có thể không thật? (Chọn Có hoặc Không) - Người đó yêu cầu bạn gửi tiền. - Người đó không muốn trò chuyện qua video. - Người đó có nhiều người theo dõi trên mạng xã hội.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q8', 'thcs', 'K7', 3, 8, 'Trong khi nghiên cứu một chủ đề, kết quả tìm kiếm của bạn mang lại một số bài báo thuyết phục. Làm thế nào để biết liệu bất kỳ bài báo nào trong số này là thiên vị? (Chọn Đúng/Sai cho mỗi phát biểu) - Tác giả của bài báo đưa ra những lập luận ngang nhau của cả hai quan điểm. - Bài báo đã được đăng trên một tạp chí uy tín, được đánh giá chuyên nghiệp. - Bài báo đã được xuất bản bởi một trong những nguồn truyền thông được liệt kê trên Biểu đồ thiên vị truyền thông. - Kiểm tra các bài viết trên med', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q9', 'thcs', 'K7', 3, 9, 'Tính năng nào trong Word cho phép thêm ghi chú vào tài liệu mà không thay đổi nội dung?', 'single', 'Picture2', TRUE),
  ('thcs__k7__mt3__q10', 'thcs', 'K7', 3, 10, 'Với mỗi câu phát biểu về thu thập thông tin phản hồi từ nhân viên, hãy chọn Đúng hoặc Sai: - Viết blog về công việc mà người sử dụng lao động đã giao cho bạn. - Yêu cầu mọi người trên mạng xã hội đăng ý tưởng của họ. - Gửi một cuộc khảo sát qua Email cho tất cả nhân viên của công ty. - Đăng biểu mẫu trên trang web của công ty và mời tất cả nhân viên hoàn thành biểu mẫu.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q11', 'thcs', 'K7', 3, 11, 'Với mỗi phát biểu, hãy chọn Đúng hoặc Sai: - Bạn là người tích cực tham gia một khóa học trực tuyến. - Bạn đang xem một cách thụ động một bài giảng trực tuyến với hàng trăm người xem khác. - Bất cứ lúc nào một ứng dụng yêu cầu quyền truy cập vào máy ảnh của bạn và không có lý do gì để cần nó.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q12', 'thcs', 'K7', 3, 12, 'Công việc của bạn đòi hỏi bạn phải làm việc với máy tính nhiều giờ mỗi ngày. Bạn lo lắng rằng bạn sẽ bị mỏi mắt. Với mỗi hành động, hãy chọn Có nếu hành động đó gây mỏi mắt hoặc Không nếu không: - Thường xuyên chớp mắt - Làm việc trong phòng tối - Thường xuyên thay đổi tiêu điểm từ màn hình máy tính sang một thứ gì đó cách xa bạn ít nhất sáu mét - Đặt màn hình sao cho cách bạn một khoảng bằng cánh tay và phần trên cùng của màn hình ngang tầm mắt của bạn.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q13', 'thcs', 'K7', 3, 13, 'Trong hội thảo trực tuyến, bạn nên thực hiện những hành động nào? (Chọn 2 đúng)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q14', 'thcs', 'K7', 3, 14, 'Phát biểu nào là đúng về tổ chức hội thảo trên Web (Webinar)? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q15', 'thcs', 'K7', 3, 15, 'Quản lý của bạn yêu cầu bạn bảo vệ tất cả các tập tin của mình bằng mật khẩu và lưu trữ những tập tin bạn không thể bảo vệ trên ổ đĩa mạng. Bạn phải di chuyển tập tin nào vào ổ đĩa mạng?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q16', 'thcs', 'K7', 3, 16, 'Với mỗi câu về tư thế ngồi làm việc, hãy chọn Có (đúng tư thế) hoặc Không (sai tư thế): - Đầu gối của bạn cao hơn hông. - Bàn chân của bạn đặt phẳng trên sàn hoặc chỗ để chân. - Cánh tay của bạn tạo thành một góc 90 độ với khuỷu tay.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q17', 'thcs', 'K7', 3, 17, 'Hai lợi ích của việc cộng tác làm việc là gì? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q18', 'thcs', 'K7', 3, 18, 'Trong trình duyệt Google Chrome, để vô hiệu hóa quyền truy cập vào máy ảnh, sắp xếp các bước theo thứ tự đúng. Ghép Bước với hành động tương ứng:', 'matching', NULL, FALSE),
  ('thcs__k7__mt3__q19', 'thcs', 'K7', 3, 19, 'Đâu là hai ví dụ về hội chứng FOMO (sợ bỏ lỡ)? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q20', 'thcs', 'K7', 3, 20, 'Hai nguyên tắc thống nhất về hình ảnh trong bài trình chiếu là gì? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q21', 'thcs', 'K7', 3, 21, 'Bạn tạo một tài liệu dài có nhiều phần nội dung. Bạn chèn tiêu đề vào phần đầu của mỗi phần nội dung. Tùy chọn nào sau đây là lý do mà bạn nên định dạng Style? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q22', 'thcs', 'K7', 3, 22, 'Nối từng phần tử cửa sổ làm việc với định nghĩa tương ứng: 1. Thanh trạng thái (Status Bar) 2. Tab trang tính (Sheet Tab) 3. Thanh công thức (Formula Bar) 4. Cột (Column)', 'matching', NULL, FALSE),
  ('thcs__k7__mt3__q23', 'thcs', 'K7', 3, 23, 'Bạn cần bảo vệ sự riêng tư và bảo mật của mình một cách thích hợp. Bạn nên tắt camera trên thiết bị trực tuyến của mình trong hai trường hợp nào? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q24', 'thcs', 'K7', 3, 24, 'Loại chỉnh sửa nào cũng được biết đến như là hợp tác đồng tác giả (Coauthoring)?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q25', 'thcs', 'K7', 3, 25, 'Kéo từng tùy chọn chỉnh sửa hình ảnh bên phải phù hợp với mục đích sử dụng tương ứng bên trái: 1. Sửa lỗi trên hình ảnh 2. Giảm kích thước của hình ảnh 3. Thay đổi độ mờ trên hình ảnh', 'matching', NULL, FALSE),
  ('thcs__k7__mt3__q26', 'thcs', 'K7', 3, 26, 'Nối các công cụ cộng tác kỹ thuật số thích hợp với mô tả trong từng: 1. Hội thảo trực tuyến 2. Bảng trắng trực tuyến 3. Chia sẻ tập tin trên nền tảng đám mây', 'matching', NULL, FALSE),
  ('thcs__k7__mt3__q27', 'thcs', 'K7', 3, 27, 'Hai khía cạnh nào của sự hiện diện trực tuyến của một người đóng góp vào danh tính kỹ thuật số nghề nghiệp của người đó? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q28', 'thcs', 'K7', 3, 28, 'Ghép từng thuật ngữ chỉnh sửa video với định nghĩa tương ứng: 1. Ghép (Splice) 2. Cắt tỉa (Trim) 3. Phân tách (Split) 4. Cắt xén (Crop)', 'matching', NULL, FALSE),
  ('thcs__k7__mt3__q29', 'thcs', 'K7', 3, 29, 'Biểu tượng nào trong hình đại diện cho chức năng Bluetooth?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q30', 'thcs', 'K7', 3, 30, 'Khớp từng phím tắt với chức năng của nó: 1. Cut 2. Copy 3. Paste 4. Select All Text', 'matching', NULL, FALSE),
  ('thcs__k7__mt3__q31', 'thcs', 'K7', 3, 31, 'Bạn cần thay Hình ảnh 1 thành Hình ảnh 2 bằng cách: Xóa hình tròn ở bên trái của ảnh. Chuyển ảnh từ có màu thành đơn sắc. Bạn nên sử dụng hai công cụ chỉnh sửa ảnh nào? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q32', 'thcs', 'K7', 3, 32, 'Với mỗi phát biểu về thiên vị truyền thông, hãy chọn Đúng (tuyên bố đúng) hoặc Sai (tuyên bố sai): - Những câu chuyện được đăng tải bởi một mạng lưới truyền thông lớn luôn thể hiện cả hai mặt và một góc nhìn bình đẳng. - Một khuynh hướng cánh tả ủng hộ bình đẳng xã hội, chủ nghĩa tự do và các ý tưởng cách mạng. - Thành kiến của cánh hữu ủng hộ các doanh nghiệp tự do, quyền sở hữu tư nhân và các ý tưởng bảo thủ về mặt xã hội. - Tất cả các câu chuyện đăng trên Internet đều có quan điểm trung lập.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q33', 'thcs', 'K7', 3, 33, 'Bryce đang bị lo lắng và trầm cảm do hội chứng sợ bỏ lỡ (FOMO). Tùy chọn nào sau đây là triệu chứng hoặc ảnh hưởng của hội chứng FOMO? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q34', 'thcs', 'K7', 3, 34, 'Cách đặt tên phiên bản tập tin nào sau đây là đúng nhất?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q35', 'thcs', 'K7', 3, 35, 'Với mỗi yếu tố để đánh giá độ tin cậy của nghiên cứu báo chí, hãy chọn Đúng hoặc Sai: - Chuyên môn và uy tín của nhà báo. - Có bao nhiêu người đã chia sẻ nghiên cứu trên mạng xã hội. - Bạn có thể tìm và truy cập các nguồn. - Nhà báo sử dụng kiến thức địa phương.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q36', 'thcs', 'K7', 3, 36, 'Nối từng hành động với phím tắt để thực hiện hành động tương ứng trong tài liệu: 1. Hoàn tác 2. Dán nội dung của bảng tạm 3. In 4. Cắt nội dung vào bảng tạm', 'matching', NULL, FALSE),
  ('thcs__k7__mt3__q37', 'thcs', 'K7', 3, 37, 'Những yếu tố nào được coi là tác động tiêu cực của FOMO? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt3__q38', 'thcs', 'K7', 3, 38, 'Sắp xếp các bước cộng tác qua tài liệu đám mây theo thứ tự đúng. Ghép Bước với hành động tương ứng:', 'matching', NULL, FALSE),
  ('thcs__k7__mt3__q39', 'thcs', 'K7', 3, 39, 'Bạn hãy cho biết kiểu chỉnh sửa nào không được thực hiện trong thời gian thực giữa hai người?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q40', 'thcs', 'K7', 3, 40, 'Thứ tự các bước khuyến nghị để tạo bài trình chiếu slide. Ghép Bước với hành động tương ứng:', 'matching', NULL, FALSE),
  ('thcs__k7__mt3__q41', 'thcs', 'K7', 3, 41, 'Đâu là tài nguyên hỗ trợ tốt nhất khi bạn gặp sự cố với phần mềm?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q42', 'thcs', 'K7', 3, 42, 'Mục đích chính của việc lập phiên bản tập tin là gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q43', 'thcs', 'K7', 3, 43, 'Khi điền vào biểu mẫu, điều nào sau đây là đúng? Với mỗi phát biểu về việc điền vào biểu mẫu, hãy chọn Đúng nếu phát biểu là đúng hoặc Sai nếu sai: - Khi được chọn nhiều hộp kiểm (check box) trong bộ chọn, bạn chỉ có thể chọn một. - Nếu bạn giữ phím Ctrl, bạn có thể chọn nhiều mục từ danh sách thả xuống. - Sau khi điền vào biểu mẫu, câu trả lời của bạn sẽ không được ghi lại cho đến khi bạn nhấp vào nút gửi. - Khi được chọn nhiều tùy chọn (Option/Radio) trong bộ chọn, nếu bạn giữ phím Ctrl, bạn c', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q44', 'thcs', 'K7', 3, 44, 'Thanh toán kỹ thuật số hoạt động như thế nào?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q45', 'thcs', 'K7', 3, 45, 'Trong giao diện tìm kiếm Google, bộ lọc nào đang được chọn (hiển thị ở trạng thái active)?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q46', 'thcs', 'K7', 3, 46, 'Với mỗi nguồn, hãy chọn Có nếu nó là nguồn phù hợp để nghiên cứu về lợi ích của giáo dục trực tuyến hoặc Không nếu không: - Bài báo về lợi ích của giáo dục. - Trang Web bán tài nguyên giáo dục. - Biểu đồ so sánh điểm kiểm tra của học sinh trong hệ thống giáo dục trực tuyến và trực tiếp. - Bài báo trên tạp chí giáo dục về kinh nghiệm giảng dạy trực tuyến của giáo viên.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt3__q47', 'thcs', 'K7', 3, 47, 'Chức năng nào của công cụ cộng tác kỹ thuật số là cho phép nhiều người dùng làm việc cùng lúc trên tài liệu?', 'single', NULL, FALSE),
  ('thcs__k7__mt3__q48', 'thcs', 'K7', 3, 48, 'Với mỗi yếu tố để đánh giá độ tin cậy của bài viết, hãy chọn Có nếu bạn phải xem xét hoặc Không nếu không: - Nguồn tài trợ bài viết. - Ngày xuất bản bài viết. - Trình độ giáo dục của tác giả. - Mối liên hệ của tác giả với các tổ chức chính trị.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt4__q1', 'thcs', 'K7', 4, 1, 'Đối với mỗi phát biểu sau đây, hãy chọn Đúng nếu nó hiển thị mức độ nhạy cảm với sự đa dạng văn hóa hoặc Sai nếu không: - Chú ý đến những định kiến và thành kiến của chính bạn. - Đặt câu hỏi thay vì đưa ra giả định. - Mua một bộ quần áo thiêng liêng được mặc bởi một nền văn hóa khác và mặc nó để thể hiện rằng bạn muốn trở thành bạn của nhau. - Đăng nhiều câu chuyện về một nền văn hóa khác trên các trang mạng xã hội của bạn.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt4__q2', 'thcs', 'K7', 4, 2, 'Ai đó trên trang mạng xã hội yêu thích của bạn vừa đăng thông tin không chính xác về một sự kiện lịch sử của Mỹ. Hai câu trả lời nào tuân theo Netiquette kỹ thuật số? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q3', 'thcs', 'K7', 4, 3, 'Bạn đang nộp đơn xin việc. Nhà tuyển dụng tiềm năng sẽ truy cập hồ sơ công việc trực tuyến của bạn. Bạn cần làm gì để hỗ trợ hồ sơ công việc trực tuyến của mình?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q4', 'thcs', 'K7', 4, 4, 'Với mỗi yếu tố để đánh giá độ tin cậy của nghiên cứu báo chí, hãy chọn Đúng hoặc Sai: - Chuyên môn và uy tín của nhà báo. - Có bao nhiêu người đã chia sẻ nghiên cứu trên mạng xã hội. - Bạn có thể tìm và truy cập các nguồn. - Nhà báo sử dụng kiến thức địa phương.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt4__q5', 'thcs', 'K7', 4, 5, 'Bạn tạo một tài liệu dài có nhiều phần nội dung. Bạn chèn tiêu đề vào phần đầu của mỗi phần nội dung. Tùy chọn nào sau đây là lý do mà bạn nên định dạng Style? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q6', 'thcs', 'K7', 4, 6, 'Điều nào sau đây là đúng khi chuẩn bị cho hội thảo video? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q7', 'thcs', 'K7', 4, 7, 'Với mỗi phát biểu về thiên vị truyền thông, hãy chọn Đúng (tuyên bố đúng) hoặc Sai (tuyên bố sai): - Những câu chuyện được đăng tải bởi một mạng lưới truyền thông lớn luôn thể hiện cả hai mặt và một góc nhìn bình đẳng. - Một khuynh hướng cánh tả ủng hộ bình đẳng xã hội, chủ nghĩa tự do và các ý tưởng cách mạng. - Thành kiến của cánh hữu ủng hộ các doanh nghiệp tự do, quyền sở hữu tư nhân và các ý tưởng bảo thủ về mặt xã hội. - Tất cả các câu chuyện đăng trên Internet đều có quan điểm trung lập.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt4__q8', 'thcs', 'K7', 4, 8, 'Loại máy in nào phun mực lên giấy khi in?', 'single', 'Picture29', TRUE),
  ('thcs__k7__mt4__q9', 'thcs', 'K7', 4, 9, 'Đâu là hai ví dụ về hội chứng FOMO (sợ bỏ lỡ)? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q10', 'thcs', 'K7', 4, 10, 'Với mỗi câu phát biểu về sức khỏe kỹ thuật số, hãy chọn Đúng hoặc Sai: - Để tránh mỏi mắt, bạn nên chớp mắt thường xuyên theo quy tắc ''20-20-20''. - Để giúp tránh rối loạn giấc ngủ, trước khi đi ngủ, hãy sạc điện thoại ở nơi bạn không thể tiếp cận nhưng vẫn có thể nghe thấy. - Để tránh nghiện mạng xã hội, bạn nên nghỉ ngơi khi duyệt 3-5 trang mạng xã hội. - Để chống lại tình trạng lười vận động, hãy mua một chiếc đồng hồ thể dục để đeo đến trường.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt4__q11', 'thcs', 'K7', 4, 11, 'Lý do chính để lấy chứng chỉ IT là gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q12', 'thcs', 'K7', 4, 12, 'Xác định ưu điểm của máy in phun và máy in laser. Hãy chọn loại máy in tương ứng với từng ưu điểm: - Tài liệu khô ngay khi in ra. - Thân thiện với môi trường hơn. - Phù hợp để in số lượng ít. - Thích hợp để in tài liệu số lượng lớn với chi phí thấp.', 'matching', 'Picture29', TRUE),
  ('thcs__k7__mt4__q13', 'thcs', 'K7', 4, 13, 'Tùy chọn nào sau đây là phát biểu đúng về quyền đối với tập tin tài liệu? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q14', 'thcs', 'K7', 4, 14, 'Với mỗi câu phát biểu về điện toán đám mây, hãy chọn Đúng hoặc Sai: - Lưu trữ tập tin trên đám mây kém an toàn hơn so với lưu trữ tập tin cục bộ. - Các ứng dụng đám mây phải được cập nhật thủ công. - Các ứng dụng và lưu trữ trên đám mây sẽ không có khả năng bị gặp sự cố dịch vụ. - Bạn có thể truy cập các tập tin được lưu trữ trong bộ nhớ đám mây từ bất cứ nơi đâu có kết nối Internet.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt4__q15', 'thcs', 'K7', 4, 15, 'Bạn cần xác định xem một bài báo trình bày thông tin theo hướng thiên vị. Đâu là hai dấu hiệu cho thấy bài báo trình bày có thiên vị? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q16', 'thcs', 'K7', 4, 16, 'Chức năng nào của công cụ cộng tác kỹ thuật số là cho phép nhiều người dùng làm việc cùng lúc trên tài liệu?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q17', 'thcs', 'K7', 4, 17, 'Nối các công cụ cộng tác kỹ thuật số thích hợp với mô tả trong từng: 1. Hội thảo trực tuyến 2. Chia sẻ tập tin trên nền tảng đám mây 3. Bảng trắng trực tuyến', 'matching', NULL, FALSE),
  ('thcs__k7__mt4__q18', 'thcs', 'K7', 4, 18, 'Nối từng phần mở rộng tập tin với mô tả định dạng tập tin trong từng: - Tập tin hình vách quét với tính năng nén không mất dữ liệu, hỗ trợ hình ảnh trong suốt - Tập tin văn bản chỉ hỗ trợ văn bản thuần - Tập tin hình vách quét có độ nén cao hỗ trợ chứa nhiều hình ảnh trong một tập tin - Tập tin văn bản hỗ trợ văn bản và đồ họa được định dạng', 'matching', NULL, FALSE),
  ('thcs__k7__mt4__q19', 'thcs', 'K7', 4, 19, 'Những yếu tố nào được coi là tác động tiêu cực của FOMO? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q20', 'thcs', 'K7', 4, 20, 'Khớp từng cáp với thiết bị mà nó thường kết nối: 1. Thiết bị chuyển mạch (Switch) 2. Loa (Speakers) 3. Truyền hình (Television) 4. Bàn phím (Keyboard)', 'matching', NULL, FALSE),
  ('thcs__k7__mt4__q21', 'thcs', 'K7', 4, 21, 'Đâu là tài nguyên hỗ trợ tốt nhất khi bạn gặp sự cố với phần mềm?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q22', 'thcs', 'K7', 4, 22, 'Bạn tạo và điền vào tài liệu một trang, sau đó thêm một trang trống vào tài liệu đó. Bạn cần sao chép tất cả nội dung của trang đầu tiên lên trang thứ hai. Bạn nên sử dụng ba phím tắt nào?', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q23', 'thcs', 'K7', 4, 23, 'Công cụ chỉnh sửa hình ảnh nào được dùng để cắt bỏ những phần không mong muốn?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q24', 'thcs', 'K7', 4, 24, 'Khi mô tả Điện toán đám mây, điều nào sau đây sẽ được coi là ưu điểm? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q25', 'thcs', 'K7', 4, 25, 'Xem email sau đây - lỗi nào trong email này vi phạm nguyên tắc nghi thức email? ''Kính gửi bà Smith, Tôi bị bận vào giờ phỏng vấn rồi, chắc là phải đổi lịch thì HY VỌNG ĐIỀU... Cảm ơn nhé!!!''', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q26', 'thcs', 'K7', 4, 26, 'Trong giao diện tìm kiếm Google, bộ lọc nào đang được chọn (hiển thị ở trạng thái active)?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q27', 'thcs', 'K7', 4, 27, 'Biểu tượng hình mặt trời trên bảng điều khiển thường đại diện cho cài đặt nào?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q28', 'thcs', 'K7', 4, 28, 'Với mỗi câu phát biểu về Macro trong một trang tính Excel, hãy chọn Đúng hoặc Sai: - Mỗi Macro được lưu trữ thành một tập tin văn bản. - Bạn có thể tạo ra Macro bằng cách viết lệnh trong trình soạn thảo lệnh. - Macro là chuỗi sự kiện có thể được phát lại, giúp thực hiện các tác vụ lặp lại. - Bạn có thể tạo một Macro bằng cách ghi lại một loạt lệnh, nhấn phím và bấm chuột.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt4__q29', 'thcs', 'K7', 4, 29, 'Thiết bị xuất nào sau đây được sử dụng để điều khiển âm thanh?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q30', 'thcs', 'K7', 4, 30, 'Ghép từng quyền tập tin với định nghĩa tương ứng: 1. Xem nội dung tập tin, thêm dữ liệu vào tập tin và xóa tập tin 2. Thêm dữ liệu vào tập tin và đọc hoặc thay đổi các thuộc tính 3. Xem hoặc truy cập nội dung tập tin 4. Xem hoặc truy cập nội dung tập tin và chạy tập tin nếu đó là một chương trình', 'matching', NULL, FALSE),
  ('thcs__k7__mt4__q31', 'thcs', 'K7', 4, 31, 'Với mỗi câu về tư thế ngồi làm việc, hãy chọn Có (đúng tư thế) hoặc Không (sai tư thế): - Đầu gối của bạn cao hơn hông. - Bàn chân của bạn đặt phẳng trên sàn hoặc chỗ để chân. - Cánh tay của bạn tạo thành một góc 90 độ với khuỷu tay.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt4__q32', 'thcs', 'K7', 4, 32, 'Trong trình duyệt Google Chrome, để vô hiệu hóa quyền truy cập vào máy ảnh, sắp xếp các bước theo thứ tự đúng. Ghép Bước với hành động tương ứng:', 'matching', NULL, FALSE),
  ('thcs__k7__mt4__q33', 'thcs', 'K7', 4, 33, 'Bạn đang sử dụng máy tính xách tay để làm việc trong khu vực ngoài trời đầy nắng. Bạn cần giảm thiểu tình trạng mỏi mắt. Bạn nên điều chỉnh cài đặt màn hình nào?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q34', 'thcs', 'K7', 4, 34, 'Với mỗi câu phát biểu về bộ xử lý trung tâm (CPU), hãy chọn Đúng hoặc Sai: - Hầu hết các bộ xử lý trung tâm hiện đại đều được xây dựng để hỗ trợ các hệ thống 64-bit. - CPU thường có bộ tản nhiệt khí hoặc tản nhiệt nước đi kèm. - Tốc độ CPU ảnh hưởng đến số khung hình trên giây (fps) hiển thị trong trò chơi 3D.', 'truefalse', NULL, FALSE),
  ('thcs__k7__mt4__q35', 'thcs', 'K7', 4, 35, 'Biểu tượng nào trong hình đại diện cho chức năng cài đặt (Settings)?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q36', 'thcs', 'K7', 4, 36, 'Hai nguyên tắc thiết kế chung cho phần cứng máy tính là gì? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q37', 'thcs', 'K7', 4, 37, 'Bạn có hai tài khoản Microsoft: tài khoản gia đình và tài khoản chơi game. Làm thế nào để chuyển đổi giữa hai tài khoản?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q38', 'thcs', 'K7', 4, 38, 'Bạn có video khoa học muốn chia sẻ với các bạn cùng lớp. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k7__mt4__q39', 'thcs', 'K7', 4, 39, 'Xác định các trường của một Email. Hãy chuyển từng trường bên phải sang chức năng của nó ở bên trái: 1. Gửi bản sao đến những người nhận ẩn danh khác 2. Phần nội dung Email 3. Danh sách những người nhận được biết khác 4. Chủ đề của Email 5. Các đánh dấu mức độ quan trọng của thư', 'matching', NULL, FALSE),
  ('thcs__k7__mt4__q40', 'thcs', 'K7', 4, 40, 'Hai nguyên tắc thống nhất về hình ảnh trong bài trình chiếu là gì? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k7__mt4__q41', 'thcs', 'K7', 4, 41, 'Với mỗi yếu tố để đánh giá độ tin cậy của bài viết, hãy chọn Có nếu bạn phải xem xét hoặc Không nếu không: - Mức độ phổ biến của nghiên cứu. - Tổ chức tài trợ cho nghiên cứu. - Đơn vị công bố kết quả nghiên cứu.', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt1__q1', 'thcs', 'K8', 1, 1, 'Loại tập tin WAV thường được sử dụng cho những loại phương tiện nào? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q2', 'thcs', 'K8', 1, 2, 'Tùy chọn nào sau đây có thể gây ra sự mơ hồ trong giao tiếp bằng văn bản? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q3', 'thcs', 'K8', 1, 3, 'Có bao nhiêu bước trong chu trình quản lý dự án?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q4', 'thcs', 'K8', 1, 4, 'Bạn là một trưởng nhóm. Nhóm của bạn đang làm việc trên môi trường ảo. Bạn cần xây dựng niềm tin và cách thức giao tiếp giữa các thành viên trong khi tham gia họp trực tuyến. Bạn nên thực hiện hành động nào? (chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q5', 'thcs', 'K8', 1, 5, 'Bạn nên quét vi-rút vì hai lý do nào? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q6', 'thcs', 'K8', 1, 6, 'Bạn đã được chỉ định lãnh đạo nhóm dịch vụ khách hàng... Đối với mỗi phát biểu sau đây, hãy chọn Đúng nếu đạt được thành công trong một nhóm ảo hoặc Sai nếu không.', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt1__q7', 'thcs', 'K8', 1, 7, 'Lựa chọn nào đóng vai trò tốt nhất trong việc định hình quan điểm của một người nào đó? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q8', 'thcs', 'K8', 1, 8, 'Một trong những hành động quan trọng nhất mà bạn có thể thực hiện để bảo vệ quyền riêng tư của mình sau khi duyệt Internet là gì?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q9', 'thcs', 'K8', 1, 9, 'Bạn đang cùng với các bạn học thực hiện một dự án nhóm. Chỉ còn ba ngày nữa là đến hạn... Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q10', 'thcs', 'K8', 1, 10, 'Bạn bắt đầu kinh doanh nhỏ. Bạn và nhân viên của mình sẽ sử dụng bộ phần mềm cơ bản Microsoft Office... Lợi ích của việc sử dụng ứng dụng trên máy tính so với sử dụng ứng dụng trên nền tảng điện toán đám mây là gì?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q11', 'thcs', 'K8', 1, 11, 'Với mỗi câu phát biểu về điện toán đám mây, hãy chọn Đúng hoặc Sai:', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt1__q12', 'thcs', 'K8', 1, 12, 'Khi tùy chỉnh điện thoại di động, bạn thường điều chỉnh cài đặt nào dưới đây? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q13', 'thcs', 'K8', 1, 13, 'Khi nhấp vào biểu tượng loa trên thanh tác vụ, chức năng nào sau đây được thực hiện?', 'single', 'Picture1', TRUE),
  ('thcs__k8__mt1__q14', 'thcs', 'K8', 1, 14, 'Tính năng nào trong Excel tự động điền dữ liệu dựa trên mẫu đã có?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q15', 'thcs', 'K8', 1, 15, 'Loại máy in nào phun mực lên giấy khi in?', 'single', 'Picture29', TRUE),
  ('thcs__k8__mt1__q16', 'thcs', 'K8', 1, 16, 'Với mỗi câu phát biểu về bộ xử lý trung tâm (CPU), hãy chọn Đúng hoặc Sai:', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt1__q17', 'thcs', 'K8', 1, 17, 'Hai điểm khác biệt nào phân biệt giữa máy in Laser và máy in phun? (Chọn 2)', 'multi', 'Picture29', TRUE),
  ('thcs__k8__mt1__q18', 'thcs', 'K8', 1, 18, 'Phần cứng nào trong máy xử lý hiệu suất của video và đồ họa?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q19', 'thcs', 'K8', 1, 19, 'Tính năng nào trong Word tự động sửa lỗi chính tả khi gõ?', 'single', 'Picture2', TRUE),
  ('thcs__k8__mt1__q20', 'thcs', 'K8', 1, 20, 'Cài đặt màn hình nào giúp tăng độ sáng của hình ảnh?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q21', 'thcs', 'K8', 1, 21, 'Nối từng hình thức giao tiếp với tình huống đang sử dụng hình thức đó:', 'matching', NULL, FALSE),
  ('thcs__k8__mt1__q22', 'thcs', 'K8', 1, 22, 'Khi tạo cuộc hẹn hoặc nhiệm vụ trên lịch kỹ thuật số cá nhân, bạn thường có thể tùy chỉnh hai cài đặt nào sau đây? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q23', 'thcs', 'K8', 1, 23, 'Biểu tượng hình mặt trời trên bảng điều khiển thường đại diện cho cài đặt nào?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q24', 'thcs', 'K8', 1, 24, 'Bạn cần chuyển từ tài khoản Google cá nhân sang tài khoản Google trường học. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q25', 'thcs', 'K8', 1, 25, 'Bạn hãy chọn tính năng dùng để chia sẻ toàn bộ lịch với người khác trong Microsoft Outlook Calendar:', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q26', 'thcs', 'K8', 1, 26, 'Hai nguyên tắc thiết kế chung cho phần cứng máy tính là gì? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q27', 'thcs', 'K8', 1, 27, 'Bạn đang sử dụng điện thoại Android và muốn giảm độ sáng để tiết kiệm pin. Tính năng nào sau đây cho phép bạn điều chỉnh độ sáng? (Chọn 1)', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q28', 'thcs', 'K8', 1, 28, 'Tùy chọn nào sau đây là phát biểu đúng về quyền đối với tập tin tài liệu? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q29', 'thcs', 'K8', 1, 29, 'Thiết bị xuất nào sau đây được sử dụng để điều khiển âm thanh?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q30', 'thcs', 'K8', 1, 30, 'Các nhà cung cấp bán nhiều hàng hóa và dịch vụ trực tuyến. Tùy chọn nào sau đây là dịch vụ? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q31', 'thcs', 'K8', 1, 31, 'Ghép nguyên tắc thiết kế với định nghĩa đúng:', 'matching', NULL, FALSE);
INSERT INTO minitest_questions (uid, cat_id, level_id, minitest_num, sort_order, question_text, question_type, image_id, has_image) VALUES
  ('thcs__k8__mt1__q32', 'thcs', 'K8', 1, 32, 'Bạn cần thêm cuộc họp Hội đồng sinh viên vào lịch. Bạn có thể lựa chọn hai phần tử nào sau đây để mở hộp thoại tạo sự kiện? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt1__q33', 'thcs', 'K8', 1, 33, 'Bạn viết một bài luận. Một người bạn cùng lớp nhận xét... Bạn cần thực hiện các sửa chữa vĩnh viễn... Bạn nên sử dụng nút nào?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q34', 'thcs', 'K8', 1, 34, 'Sắp xếp các bước tạo bảng điểm trò chơi trong trang tính theo đúng thứ tự:', 'matching', NULL, FALSE),
  ('thcs__k8__mt1__q35', 'thcs', 'K8', 1, 35, 'Bạn đang thêm ngày sinh của bố mình vào lịch cá nhân. Hãy nối từng tùy chỉnh với cài đặt sự kiện tương ứng:', 'matching', NULL, FALSE),
  ('thcs__k8__mt1__q36', 'thcs', 'K8', 1, 36, 'Phương pháp nào được sử dụng để chuyển đổi dữ liệu thành định dạng không thể đọc được để bảo vệ thông tin?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q37', 'thcs', 'K8', 1, 37, 'Với mỗi câu phát biểu về tính bảo mật của thiết bị đa phương tiện di động, hãy chọn Đúng hoặc Sai:', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt1__q38', 'thcs', 'K8', 1, 38, 'Với mỗi câu phát biểu về cáp kết nối, hãy chọn Đúng hoặc Sai:', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt1__q39', 'thcs', 'K8', 1, 39, 'Ghép từng bên tham gia thanh toán kỹ thuật số với định nghĩa tương ứng:', 'matching', NULL, FALSE),
  ('thcs__k8__mt1__q40', 'thcs', 'K8', 1, 40, 'Với mỗi câu phát biểu về hệ thống lưu trữ dữ liệu trung tâm, hãy chọn Đúng hoặc Sai:', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt1__q41', 'thcs', 'K8', 1, 41, 'Lợi thế của việc sử dụng ví điện tử như Apple Pay hoặc Google Pay là gì?', 'single', NULL, FALSE),
  ('thcs__k8__mt1__q42', 'thcs', 'K8', 1, 42, 'Ghép từng loại tập tin với phần mở rộng phù hợp:', 'matching', NULL, FALSE),
  ('thcs__k8__mt2__q1', 'thcs', 'K8', 2, 1, 'Cách tốt nhất để bảo vệ quyền riêng tư trực tuyến tại nơi làm việc của bạn là gì?', 'single', NULL, FALSE),
  ('thcs__k8__mt2__q2', 'thcs', 'K8', 2, 2, 'Bạn đang tạo một trang Web dễ dàng tiếp cận. Với mỗi hành động thiết kế sau đây, hãy chọn Có nếu là tiêu chuẩn thực tiến tốt nhất. Ngược lại, hãy chọn Không', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt2__q3', 'thcs', 'K8', 2, 3, 'Bạn cần chọn một dự án để nói lên cách hiểu của mình về một cuốn tiểu thuyết... Nối từng ứng dụng với tác vụ thích hợp.', 'matching', NULL, FALSE),
  ('thcs__k8__mt2__q4', 'thcs', 'K8', 2, 4, 'Trong tiết khoa học, bạn cần phân tích các bảng số liệu. Bạn nên sử dụng ứng dụng phần mềm nào sau đây?', 'single', NULL, FALSE),
  ('thcs__k8__mt2__q5', 'thcs', 'K8', 2, 5, 'Bạn thiết kế một trang Web cho trường học để theo dõi sự tham gia của sinh viên vào các câu lạc bộ... Bạn nên thực hiện hai hành động nào để đảm bảo nhận được dữ liệu kiểm thử chất lượng? (chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt2__q6', 'thcs', 'K8', 2, 6, 'Bạn là thành viên của một nhóm sinh viên đang tạo trang Web cho một tổ chức địa phương... Tùy chọn nào sau đây là hành động mà bạn có thể thực hiện để cải thiện kỹ năng giao tiếp của mình? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt2__q7', 'thcs', 'K8', 2, 7, 'Loại phông chữ nào sau đây được coi là tốt hơn để đọc trên màn hình?', 'single', NULL, FALSE),
  ('thcs__k8__mt2__q8', 'thcs', 'K8', 2, 8, 'Ghép mỗi mô tả với hình dạng tương ứng trong sơ đồ quy trình (flowchart):', 'matching', NULL, FALSE),
  ('thcs__k8__mt2__q9', 'thcs', 'K8', 2, 9, 'Bạn được giao nhiệm vụ thiết kế một trang Web nhằm đạt được các mục tiêu sau đây... Hai tiêu chí trang Web nào ràng buộc về thiết kế? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt2__q10', 'thcs', 'K8', 2, 10, 'Bạn đang thêm văn bản thay thế (Alt Text) vào hình ảnh trên trang Web của mình... Với mỗi loại thông tin sau đây, hãy chọn Có nếu cần thêm thông tin đó vào văn bản thay thế hoặc Không nếu không cần', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt2__q11', 'thcs', 'K8', 2, 11, 'Microsoft Office được biết đến với việc giúp bạn dễ dàng sử dụng các tính năng phổ biến... Giao diện người dùng nào sau đây giúp bạn dễ dàng sử dụng các tính năng chung trên các ứng dụng Microsoft Office?', 'single', NULL, FALSE),
  ('thcs__k8__mt2__q12', 'thcs', 'K8', 2, 12, 'Trường của bạn yêu cầu bạn thiết kế một trang Web để theo dõi việc tham gia vào các câu lạc bộ của sinh viên... Hành động nào sau đây sẽ có ích cho quá trình hình thành ý tưởng? (chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt2__q13', 'thcs', 'K8', 2, 13, 'Bạn tùy chỉnh phần cài đặt Google Chrome của mình... Bạn nên chọn lệnh nào?', 'single', NULL, FALSE),
  ('thcs__k8__mt2__q14', 'thcs', 'K8', 2, 14, 'Bạn cần thuyết trình một loạt hình ảnh và nội dung viết tay trong lớp lịch sử. Bạn nên sử dụng ứng dụng nào sau đây?', 'single', NULL, FALSE),
  ('thcs__k8__mt2__q15', 'thcs', 'K8', 2, 15, 'Có ba cách chỉnh sửa để thao túng nội dung Video... Phương pháp chỉnh sửa video nào sau đây thường được sử dụng để thao túng nội dung video nhằm mục đích đánh lừa người xem? (Chọn 3)', 'multi', NULL, FALSE),
  ('thcs__k8__mt2__q16', 'thcs', 'K8', 2, 16, 'Ghép mỗi mục đích hiển thị dữ liệu với loại biểu đồ phù hợp:', 'matching', NULL, FALSE),
  ('thcs__k8__mt2__q17', 'thcs', 'K8', 2, 17, 'Sự mơ hồ trong giao tiếp kỹ thuật số xảy ra khi thông điệp được truyền đạt có thể được diễn giải theo nhiều cách. Lựa chọn nào sau đây là hậu quả của sự mơ hồ trong giao tiếp? (Chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt2__q18', 'thcs', 'K8', 2, 18, 'Bạn đăng một Video lên trang Web của công ty... Đối với mỗi hành động, hãy chọn Có nếu hành động đó giúp tải Video nhanh hơn. Ngược lại, hãy chọn Không', 'truefalse', NULL, FALSE),
  ('thcs__k8__mt2__q19', 'thcs', 'K8', 2, 19, 'Bạn đang tạo một trang Web dễ dàng tiếp cận... Với mỗi hành động thiết kế sau đây, hãy chọn Có/Không', 'truefalse', NULL, FALSE),
