  ('thcs__k8__mt4__q35', 'thcs', 'K8', 4, 35, 'Trường của bạn yêu cầu bạn thiết kế một trang Web... Hành động nào sau đây sẽ có ích...? (chọn 2)', 'multi', NULL, FALSE),
  ('thcs__k8__mt4__q36', 'thcs', 'K8', 4, 36, 'Bạn tùy chỉnh phần cài đặt Google Chrome... Bạn nên chọn lệnh nào?', 'single', NULL, FALSE),
  ('thcs__k8__mt4__q37', 'thcs', 'K8', 4, 37, 'Bạn cần thuyết trình một loạt hình ảnh và nội dung viết tay... Bạn nên sử dụng ứng dụng nào sau đây?', 'single', NULL, FALSE),
