  ('tih__k3__mt1__q1', 'tih', 'K3', 1, 1, 'Bạn thường tìm thấy điều gì trong ứng dụng máy tính để bàn và trên các trang Web?', 'single', 'Picture3', TRUE),
  ('tih__k3__mt1__q2', 'tih', 'K3', 1, 2, 'Nhóm nào thích hợp cho bạn bè trực tuyến?', 'single', NULL, FALSE),
  ('tih__k3__mt1__q3', 'tih', 'K3', 1, 3, 'Cách nào sau đây để kết nối máy tính bảng hoặc điện thoại thông minh với Internet? (Chọn 2)', 'multi', NULL, FALSE),
  ('tih__k3__mt1__q4', 'tih', 'K3', 1, 4, 'Thuật ngữ cho phần mềm chạy trên điện thoại hoặc máy tính bảng là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt1__q5', 'tih', 'K3', 1, 5, 'Bạn đang nói chuyện với bạn bè trên thiết bị kỹ thuật số. Với Camera tích hợp, bạn có thể nhìn thấy bạn bè. Đang sử dụng hình thức giao tiếp kỹ thuật số nào?', 'single', 'Picture5', TRUE),
  ('tih__k3__mt1__q6', 'tih', 'K3', 1, 6, 'Bạn cần đóng (Close) cửa sổ trình duyệt hiển thị. Bạn nên nhấp hoặc nhấn vào biểu tượng nào? (Chọn biểu tượng trong khu vực trả lời)', 'single', 'Picture4', TRUE),
  ('tih__k3__mt1__q7', 'tih', 'K3', 1, 7, 'An cần sạc điện thoại vào ban đêm để có thể sử dụng nó vào sáng hôm sau. Đâu là nơi an toàn để An giữ điện thoại trong khi đang sạc?', 'single', 'Picture81', TRUE),
  ('tih__k3__mt1__q8', 'tih', 'K3', 1, 8, 'Bạn muốn tìm một trò chơi được cài đặt trên máy tính của mình. Trên thanh tác vụ được hiển thị, bạn nên nhấp vào đâu để tìm trò chơi? (Chọn phần tử đúng trong khu vực trả lời.)', 'single', 'Picture1', TRUE),
  ('tih__k3__mt1__q9', 'tih', 'K3', 1, 9, 'Bạn đang học trực tuyến tại thư viện công cộng. Bạn cần sạc pin máy tính xách tay. Một người lạ đang sạc điện thoại di động ở ổ cắm gần nhất. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('tih__k3__mt1__q10', 'tih', 'K3', 1, 10, 'Trong cửa sổ trình duyệt được hiển thị, bạn nên nhấp hoặc nhấn vào đâu để truy cập các trang khác của trang Web Net PC? (Chọn vị trí chính xác trong khu vực trả lời)', 'single', 'Picture3', TRUE),
  ('tih__k3__mt1__q11', 'tih', 'K3', 1, 11, 'Đối với mỗi mật khẩu, hãy chọn Mạnh nếu mật khẩu mạnh hoặc Yếu nếu mật khẩu yếu.', 'matching', NULL, FALSE),
  ('tih__k3__mt1__q12', 'tih', 'K3', 1, 12, 'Rian đang gửi cho cô Dung một Email. Bạn ấy biết có năm phần quan trọng cần đưa vào Email. Lời chào là phần nào? (Chọn phần thích hợp trong khu vực trả lời)', 'single', 'Picture10', TRUE),
  ('tih__k3__mt1__q13', 'tih', 'K3', 1, 13, 'Bạn nhận được Email từ một người gửi không xác định nói rằng bạn đã giành được giải thưởng và yêu cầu bạn trả lời kèm theo tên, địa chỉ và số điện thoại. Điều an toàn nhất để làm tiếp theo là gì?', 'single', 'Picture17', TRUE),
  ('tih__k3__mt1__q14', 'tih', 'K3', 1, 14, 'Nối mỗi từ với định nghĩa thích hợp', 'matching', NULL, FALSE),
  ('tih__k3__mt1__q15', 'tih', 'K3', 1, 15, 'Cách nhanh nhất để lưu trang Web bạn đang xem để bạn có thể quay lại sau là gì?', 'single', 'Picture6', TRUE),
  ('tih__k3__mt1__q16', 'tih', 'K3', 1, 16, 'Bạn đang nghiên cứu trực tuyến cho một bài tập về đại dương. Giáo viên đã hướng dẫn bao gồm ít nhất ba sự thật và không có ý kiến. Tùy chọn nào sau đây là một ý kiến?', 'single', 'Picture19', TRUE),
  ('tih__k3__mt1__q17', 'tih', 'K3', 1, 17, 'Nhi thích đọc các bài báo trực tuyến. Cô ấy chỉ muốn đọc các bài báo dựa trên sự thật, không phải ý kiến. Câu hỏi nào có thể giúp Nhi xác định các bài báo dựa trên thực tế (sự thật)?', 'single', 'Picture24', TRUE),
  ('tih__k3__mt1__q18', 'tih', 'K3', 1, 18, 'Bạn gửi một Email cho lớp trưởng, bạn sẽ đặt địa chỉ email của lớp trưởng ở đâu? (Chọn vị trí chính xác trong khu vực trả lời)', 'single', 'Picture9', TRUE),
  ('tih__k3__mt1__q19', 'tih', 'K3', 1, 19, 'Thông tin cá nhân nào bạn KHÔNG nên chia sẻ trực tuyến?', 'single', NULL, FALSE),
  ('tih__k3__mt1__q20', 'tih', 'K3', 1, 20, 'Đối với mỗi phát biểu về tương tác kỹ thuật số, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('tih__k3__mt1__q21', 'tih', 'K3', 1, 21, 'Lưng mẹ bạn đau khi bà ngồi vào bàn làm việc để sử dụng máy tính. Mẹ yêu cầu bạn cho lời khuyên về cách có tư thế tốt. Bạn nên nói gì với mẹ?', 'single', NULL, FALSE),
  ('tih__k3__mt1__q22', 'tih', 'K3', 1, 22, 'Giáo viên gửi Email nhắc nhở phụ huynh có bài kiểm tra ngày mai. Bạn muốn sắp xếp một buổi học nhóm. Bạn nhắn tin cho một người bạn, gọi cho người khác và trò chuyện Video với người bạn thứ ba. Quy trình nào đang được sử dụng để gửi và nhận thông tin?', 'single', NULL, FALSE),
  ('tih__k3__mt1__q23', 'tih', 'K3', 1, 23, 'Mục tiêu là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt1__q24', 'tih', 'K3', 1, 24, 'Nhi đang viết một báo cáo trên máy tính. Bạn ấy được yêu cầu thụt lề dòng đầu tiên của mỗi đoạn một nửa inch. Nhi nên nhấn phím nào để lùi dòng đầu tiên vào 1.5 inch? (Chọn khóa thích hợp trong khu vực trả lời)', 'single', 'Picture45', TRUE),
  ('tih__k3__mt1__q25', 'tih', 'K3', 1, 25, 'Thiết bị nào có bàn di chuột tích hợp để trỏ và nhấp?', 'single', 'Picture87', TRUE),
  ('tih__k3__mt1__q26', 'tih', 'K3', 1, 26, 'Bạn và hai người bạn cùng lớp đang làm việc cùng nhau trong một dự án tạo áp phích về cá mập. Bạn sẽ in ra những bức ảnh, một người bạn sẽ mua bảng áp phích và điểm đánh dấu, người kia sẽ lắp ráp áp phích. Mục đích của công việc này là gì?', 'single', 'Picture29', TRUE),
  ('tih__k3__mt1__q27', 'tih', 'K3', 1, 27, 'Bạn sẽ tìm thấy lệnh Đóng (Close/Quit), trên thẻ (Tab) nào sau đây? (chọn thẻ trong khu vực trả lời)', 'single', 'Picture2', TRUE),
  ('tih__k3__mt1__q28', 'tih', 'K3', 1, 28, 'An cần gửi Email cảm ơn đến giáo viên của mình nhưng bạn ấy không biết nên sử dụng phông chữ nào. Phông chữ nào thích hợp nhất cho thông báo này?', 'single', 'Picture16', TRUE),
  ('tih__k3__mt1__q29', 'tih', 'K3', 1, 29, 'Di chuyển từng thuật ngữ từ danh sách bên trái sang định nghĩa của nó ở bên phải.', 'matching', NULL, FALSE),
  ('tih__k3__mt1__q30', 'tih', 'K3', 1, 30, 'Di chuyển từng định nghĩa từ danh sách bên trái sang thuật ngữ mà nó xác định ở bên phải.', 'matching', NULL, FALSE),
  ('tih__k3__mt1__q31', 'tih', 'K3', 1, 31, 'Em hãy cho biết, cần sử dụng phần mềm ứng dụng nào để tạo ra các chữ cái tiêu chuẩn thay vì sử dụng máy đánh chữ?', 'single', 'Picture7', TRUE),
  ('tih__k3__mt1__q32', 'tih', 'K3', 1, 32, 'Ví dụ về một người bạn trực tuyến thích hợp là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q1', 'tih', 'K3', 2, 1, 'Bạn gặp một người trong phòng trò chuyện chơi Game trực tuyến. Họ yêu cầu bạn cung cấp địa chỉ nhà của bạn. Bạn nên kết luận điều gì từ yêu cầu của họ?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q2', 'tih', 'K3', 2, 2, 'Bạn cần gửi một Email cho giáo viên của bạn. Bạn nên đặt địa chỉ Email của giáo viên ở đâu? (Chọn vị trí chính xác trong khu vực trả lời)', 'single', NULL, FALSE),
  ('tih__k3__mt2__q3', 'tih', 'K3', 2, 3, 'Hình ảnh này cho biết loại thiết bị máy tính nào?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q4', 'tih', 'K3', 2, 4, 'Bạn đang thực hiện một dự án nhóm về động vật. Bạn cần gửi hai bức ảnh và hai đoạn về thằn lằn cho bạn cùng lớp đang làm áp phích cho nhóm. Bạn nên gửi thông tin cho bạn cùng lớp như thế nào?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q5', 'tih', 'K3', 2, 5, 'Bạn nhập tên của mình vào một công cụ tìm kiếm. Kết quả tìm kiếm bao gồm các ảnh mà bạn đã xóa khỏi trang Web nơi bạn đã đăng chúng. Điều này có nghĩa là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q6', 'tih', 'K3', 2, 6, 'Học sinh mới cần tạo một trang Web với mật khẩu là orange mà trường học của bạn sử dụng để quản lý bài tập về nhà. Họ yêu cầu bạn cung cấp các mẹo mật khẩu. Bạn nên nói gì với họ?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q7', 'tih', 'K3', 2, 7, 'Ghép mỗi thuật ngữ với định nghĩa đúng', 'matching', NULL, FALSE),
  ('tih__k3__mt2__q8', 'tih', 'K3', 2, 8, 'Bạn đang truy cập Internet và cửa sổ hiển thị bên dưới bật lên. Đối với mỗi hành động, hãy chọn Có nếu bạn nên làm điều đó hoặc Không nếu bạn KHÔNG nên làm điều đó.', 'truefalse', NULL, FALSE),
  ('tih__k3__mt2__q9', 'tih', 'K3', 2, 9, 'Máy tính để bàn có thể sử dụng loại thiết bị nào để kết nối Internet?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q10', 'tih', 'K3', 2, 10, 'Bạn nên làm gì nếu bạn bị người lạ có hành vi trực tuyến tục tĩu không phù hợp?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q11', 'tih', 'K3', 2, 11, 'Bạn cần sử dụng máy tính bảng (Tablet) của mình trong giờ học để tham gia vào các bài học. Bạn nhận thấy rằng thời lượng pin đang trở nên yếu. Bộ sạc của bạn không hoạt động. Bạn nên làm gì để tiếp tục tham gia trên máy tính bảng của mình?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q12', 'tih', 'K3', 2, 12, 'Bạn là đội trưởng của đội bóng đá. Bạn cần thay mặt đội bóng hỏi huấn luyện viên của mình một câu hỏi khẩn cấp. Bạn nên đặt URGENT (khẩn cấp) ở đâu để đảm bảo rằng huấn luyện viên của bạn nhận được thông báo và mở Email một cách nhanh chóng?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q13', 'tih', 'K3', 2, 13, 'Hầu hết các thư và email đều có lời chào và lời kết thúc đi. Chọn từng cụm từ từ danh sách bên phải sang đúng thể loại bên trái.', 'matching', NULL, FALSE),
  ('tih__k3__mt2__q14', 'tih', 'K3', 2, 14, 'Bằng cách sử dụng tính năng Bookmarks/Favorites của trình duyệt Web, bạn có thể lưu gì?', 'single', 'Picture6', TRUE),
  ('tih__k3__mt2__q15', 'tih', 'K3', 2, 15, 'Quyền riêng tư kỹ thuật số là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q16', 'tih', 'K3', 2, 16, 'Kịch bản nào là một ví dụ về cộng tác kỹ thuật số?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q17', 'tih', 'K3', 2, 17, 'Nhi muốn tham gia một trang mạng xã hội mới nổi tiếng. Để đăng ký, cô ấy phải điền vào một biểu mẫu trực tuyến. Nhi nên giữ phím nào trong khi gõ để chỉ viết hoa chữ cái đầu tiên trong tên của cô ấy? (chọn khóa thích hợp trong khu vực trả lời)', 'single', NULL, FALSE),
  ('tih__k3__mt2__q18', 'tih', 'K3', 2, 18, 'Nhi đã xây dựng một mô hình lớp học của mình như một bài tập về nhà. Bạn ấy muốn đưa nó cho anh của bạn ấy, người sống ở xa. Bạn ấy muốn chỉ cho anh ấy nơi bạn ấy ngồi và nói với anh ấy về giáo viên của bạn ấy và bạn bè của mình. Nhi nên thể hiện và nói với anh mình những điều này như thế nào?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q19', 'tih', 'K3', 2, 19, 'Tùy chọn nào đại diện cho một đặc điểm của công dân kỹ thuật số tốt?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q20', 'tih', 'K3', 2, 20, 'Bạn đang tìm kiếm một nơi để đi với các bạn cùng lớp. Bạn đọc một bài đánh giá trực tuyến cho một nhà hàng nghe có vẻ tốt. Đối với mỗi tuyên bố, hãy chọn Thực tế hoặc Quan điểm.', 'truefalse', NULL, FALSE),
  ('tih__k3__mt2__q21', 'tih', 'K3', 2, 21, 'Em hãy cho biết, đây là loại tập tin gì?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q22', 'tih', 'K3', 2, 22, 'Trolling là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q23', 'tih', 'K3', 2, 23, 'Một giáo viên bảo học sinh nghiên cứu một chủ đề trên máy tính bảng trong 30 phút tiếp theo. Khi giáo viên hỏi một học sinh có thực hiện nghiên cứu hay không, bạn ấy nói có. Làm thế nào giáo viên có thể tìm ra liệu học sinh có nói sự thật hay không?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q24', 'tih', 'K3', 2, 24, 'Thiết bị đầu vào (Input Device) nào sau đây được tích hợp vào điện thoại thông minh?', 'single', 'Picture84', TRUE),
  ('tih__k3__mt2__q25', 'tih', 'K3', 2, 25, 'Phát biểu nào sau đây là đúng về một phần mềm ứng dụng trên máy tính để bàn?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q26', 'tih', 'K3', 2, 26, 'Hoạt động nào là một ví dụ về sự hợp tác?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q27', 'tih', 'K3', 2, 27, 'Tùy chọn nào sau đây là một tập tin (File)?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q28', 'tih', 'K3', 2, 28, 'Nhi đang gặp bạn mình sau giờ học để học nhóm. Vào cuối giờ học, giáo viên của Nhi yêu cầu bạn ấy ở lại vài phút để giúp dọn dẹp bàn học. Nhi sẽ đến muộn để gặp bạn mình. Cách nhanh nhất để Nhi nói với bạn mình rằng bạn ấy sẽ đến muộn vài phút là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt2__q29', 'tih', 'K3', 2, 29, 'Bạn sẽ tìm thấy lệnh Đóng (Close) trên thẻ (Tab) nào sau đây? (chọn thẻ trong khu vực trả lời)', 'single', NULL, FALSE),
  ('tih__k3__mt2__q30', 'tih', 'K3', 2, 30, 'Đối với mỗi phát biểu về việc vận chuyển máy tính xách tay, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('tih__k3__mt2__q31', 'tih', 'K3', 2, 31, 'Bạn của bạn đã gửi một tin nhắn điện tử ngắn từ điện thoại của bạn ấy đến điện thoại của bạn. Tin nhắn chứa các chữ cái, số và biểu tượng cảm xúc. Bạn của bạn đã sử dụng hình thức giao tiếp kỹ thuật số nào?', 'single', NULL, FALSE);
INSERT INTO minitest_questions (uid, cat_id, level_id, minitest_num, sort_order, question_text, question_type, image_id, has_image) VALUES
  ('tih__k3__mt3__q1', 'tih', 'K3', 3, 1, 'Bạn cần kết nối máy tính bảng với Internet. Bạn nên sử dụng phương tiện gì dưới đây?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q2', 'tih', 'K3', 3, 2, 'Bạn nhận được Email từ một người gửi không xác định nói rằng bạn đã giành được giải thưởng và yêu cầu bạn trả lời kèm theo tên, địa chỉ và số điện thoại. Điều an toàn nhất để làm tiếp theo là gì?', 'single', 'Picture17', TRUE),
  ('tih__k3__mt3__q3', 'tih', 'K3', 3, 3, 'Thuật ngữ cho thời gian bạn dành để làm những việc như: Xem TV, chơi trò chơi điện tử, gửi tin nhắn văn bản, nghiên cứu máy tính là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q4', 'tih', 'K3', 3, 4, 'Tên của khu vực ở đầu cửa sổ trình duyệt hiển thị URL trang Web được gọi là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q5', 'tih', 'K3', 3, 5, 'Bạn nên sử dụng định dạng nào để trình chiếu ảnh, bản đồ và Video từ kỳ nghỉ hè của bạn cho các bạn trong lớp?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q6', 'tih', 'K3', 3, 6, 'Bạn đang học trực tuyến tại thư viện công cộng. Bạn cần sạc pin máy tính xách tay để hoàn thành công việc của mình. Một người lạ đang sạc điện thoại di động của họ ở ổ cắm gần nhất. Bạn nên làm gì để vừa sạc pin máy tính và vừa tiếp tục làm việc?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q7', 'tih', 'K3', 3, 7, 'Khi nào thì có thể nói chuyện với người lạ trực tuyến?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q8', 'tih', 'K3', 3, 8, 'Ai đó đã đăng một bình luận xấu tính trên mạng xã hội về bạn An. Bạn ấy đã xóa bình luận, nhưng cũng chính người đó đã viết những bình luận ác ý hơn. Một thuật ngữ cho người đã viết các ý kiến có nghĩa là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q9', 'tih', 'K3', 3, 9, 'Đối với mỗi mật khẩu, hãy chọn Mạnh nếu mật khẩu mạnh hoặc Yếu nếu mật khẩu yếu.', 'matching', NULL, FALSE),
  ('tih__k3__mt3__q10', 'tih', 'K3', 3, 10, 'Hành động nào là một ví dụ về bắt nạt trên mạng?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q11', 'tih', 'K3', 3, 11, 'Những cách nào điện thoại thông minh có thể kết nối với Internet? (Chọn 2)', 'multi', NULL, FALSE),
  ('tih__k3__mt3__q12', 'tih', 'K3', 3, 12, 'Thiết bị nào có bàn di chuột tích hợp để trỏ và nhấp?', 'single', 'Picture87', TRUE),
  ('tih__k3__mt3__q13', 'tih', 'K3', 3, 13, 'Phần thông tin nào là an toàn để chia sẻ trực tuyến?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q14', 'tih', 'K3', 3, 14, 'Ai đó bạn gặp trực tuyến, yêu cầu bạn cung cấp tên và địa chỉ của bạn để họ gửi cho bạn lời mời dự tiệc sinh nhật. Bạn nên làm gì?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q15', 'tih', 'K3', 3, 15, 'Thuật ngữ cho phần mềm chạy trên điện thoại hoặc máy tính bảng là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q16', 'tih', 'K3', 3, 16, 'Đối với mỗi phát biểu về việc đăng thông tin trên Internet, bạn hãy chọn đáp án Đúng hoặc Sai cho mỗi phát biểu dưới đây.', 'truefalse', NULL, FALSE),
  ('tih__k3__mt3__q17', 'tih', 'K3', 3, 17, 'Bạn nhận được một Email từ cửa hàng yêu thích của mình nói rằng bạn đã giành được 1000 đô la. Bạn có thể nhập thông tin của mình vào biểu mẫu trực tuyến để nhận tiền. Điều gì sẽ khiến bạn quan tâm về Email này?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q18', 'tih', 'K3', 3, 18, 'Đối với mỗi hành động, hãy chọn Có nếu đó là ví dụ về định dạng văn bản hoặc Không nếu không.', 'matching', NULL, FALSE),
  ('tih__k3__mt3__q19', 'tih', 'K3', 3, 19, 'Bạn có một máy tính, một màn hình và một bàn phím trong phòng của bạn. Tại sao bạn nên che bàn phím khi bạn không sử dụng nó?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q20', 'tih', 'K3', 3, 20, 'Khi ai đó sử dụng công nghệ để gây ác ý với người khác, việc họ đang làm được gọi là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q21', 'tih', 'K3', 3, 21, 'Bạn thường tìm thấy điều gì trong ứng dụng máy tính để bàn và trên các trang Web?', 'single', 'Picture3', TRUE),
  ('tih__k3__mt3__q22', 'tih', 'K3', 3, 22, 'Bạn cần truy cập một trang Web khác. Trên trang Web được hiển thị, bạn nên nhập URL mới vào đâu? (Chọn vị trí chính xác trong khu vực trả lời)', 'single', NULL, FALSE),
  ('tih__k3__mt3__q23', 'tih', 'K3', 3, 23, 'Hãy xem xét những gì bạn biết về bản chất công khai và lâu dài của nội dung trực tuyến. Nội dung nào KHÔNG an toàn để chia sẻ trực tuyến?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q24', 'tih', 'K3', 3, 24, 'Bạn thấy những bình luận ác ý trong một cuộc trò chuyện trong nhóm trực tuyến. Là một công dân tốt của thời đại kỹ nguyên số, bạn nên nói gì?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q25', 'tih', 'K3', 3, 25, 'Nhi đang viết một báo cáo trên máy tính của mình. Bạn ấy được yêu cầu thụt lề dòng đầu tiên của mỗi đoạn một nửa inch. Nhi nên nhấn phím nào để lùi dòng đầu tiên vào 1.5 inch? (Chọn khóa thích hợp trong khu vực trả lời)', 'single', 'Picture45', TRUE),
  ('tih__k3__mt3__q26', 'tih', 'K3', 3, 26, 'Di chuyển từng thuật ngữ từ danh sách bên trái sang định nghĩa của nó ở bên phải.', 'matching', NULL, FALSE),
  ('tih__k3__mt3__q27', 'tih', 'K3', 3, 27, 'Giáo viên gửi Email nhắc nhở phụ huynh có bài kiểm tra ngày mai. Bạn muốn sắp xếp một buổi học nhóm. Bạn nhắn tin cho một người bạn, gọi cho người khác và trò chuyện Video với người bạn thứ ba. Quy trình nào đang được sử dụng để gửi và nhận thông tin?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q28', 'tih', 'K3', 3, 28, 'Bạn gửi ảnh của bạn và gia đình của bạn cho một người bạn cùng lớp. Bạn cùng lớp đăng ảnh lên mạng xã hội của họ. Bạn có thể làm gì để xóa ảnh vĩnh viễn khỏi Internet?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q29', 'tih', 'K3', 3, 29, 'Bạn hãy cho biết, công cụ nào của trình duyệt cho phép truy cập vào các trang Web yêu thích?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q30', 'tih', 'K3', 3, 30, 'Bắt nạt trực tuyến (Cyberbullying) là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt3__q31', 'tih', 'K3', 3, 31, 'Bạn muốn tìm một trò chơi được cài đặt trên máy tính của mình. Trên thanh tác vụ được hiển thị, bạn nên nhấp vào đâu để tìm trò chơi? (Chọn phần tử đúng trong khu vực trả lời.)', 'single', 'Picture1', TRUE),
  ('tih__k3__mt4__q1', 'tih', 'K3', 4, 1, 'Thuật ngữ cho phần mềm chạy trên điện thoại hoặc máy tính bảng là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q2', 'tih', 'K3', 4, 2, 'Hãy xem xét những gì bạn biết về bản chất công khai và lâu dài của nội dung trực tuyến. Nội dung nào KHÔNG an toàn để chia sẻ trực tuyến?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q3', 'tih', 'K3', 4, 3, 'Giáo viên gửi Email nhắc nhở phụ huynh có bài kiểm tra ngày mai. Bạn muốn sắp xếp một buổi học nhóm. Bạn nhắn tin cho một người bạn, gọi cho người khác và trò chuyện Video với người bạn thứ ba. Quy trình nào đang được sử dụng để gửi và nhận thông tin?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q4', 'tih', 'K3', 4, 4, 'Thiết bị nào có bàn di chuột tích hợp để trỏ và nhấp?', 'single', 'Picture87', TRUE),
  ('tih__k3__mt4__q5', 'tih', 'K3', 4, 5, 'Mục tiêu là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q6', 'tih', 'K3', 4, 6, 'Bạn thường tìm thấy điều gì trong ứng dụng máy tính để bàn và trên các trang Web?', 'single', 'Picture3', TRUE),
  ('tih__k3__mt4__q7', 'tih', 'K3', 4, 7, 'An cần gửi Email cảm ơn đến giáo viên của mình nhưng bạn ấy không biết nên sử dụng phông chữ nào. Phông chữ nào thích hợp nhất cho thông báo này?', 'single', 'Picture16', TRUE),
  ('tih__k3__mt4__q8', 'tih', 'K3', 4, 8, 'Bạn sẽ tìm thấy lệnh Đóng (Close) trên thẻ (Tab) nào sau đây? (chọn thẻ trong khu vực trả lời)', 'single', NULL, FALSE),
  ('tih__k3__mt4__q9', 'tih', 'K3', 4, 9, 'Phát biểu nào sau đây là đúng về một phần mềm ứng dụng trên máy tính để bàn?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q10', 'tih', 'K3', 4, 10, 'Bạn và hai người bạn cùng lớp đang làm việc cùng nhau trong một dự án tạo áp phích về cá mập. Mục đích của công việc này là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q11', 'tih', 'K3', 4, 11, 'Cách nào sau đây để kết nối máy tính bảng hoặc điện thoại thông minh với Internet? (Chọn 2)', 'multi', NULL, FALSE),
  ('tih__k3__mt4__q12', 'tih', 'K3', 4, 12, 'Ví dụ về một người bạn trực tuyến thích hợp là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q13', 'tih', 'K3', 4, 13, 'Đối với mỗi phát biểu về việc đăng thông tin trên Internet, bạn hãy chọn đáp án Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('tih__k3__mt4__q14', 'tih', 'K3', 4, 14, 'Đối với mỗi phát biểu về việc vận chuyển máy tính xách tay, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('tih__k3__mt4__q15', 'tih', 'K3', 4, 15, 'Bạn của bạn đã gửi một tin nhắn điện tử ngắn từ điện thoại của bạn ấy đến điện thoại của bạn. Tin nhắn chứa các chữ cái, số và biểu tượng cảm xúc. Bạn của bạn đã sử dụng hình thức giao tiếp kỹ thuật số nào?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q16', 'tih', 'K3', 4, 16, 'Bạn cần đóng (Close) cửa sổ trình duyệt hiển thị. Bạn nên nhấp hoặc nhấn vào biểu tượng nào? (Chọn biểu tượng trong khu vực trả lời)', 'single', 'Picture4', TRUE),
  ('tih__k3__mt4__q17', 'tih', 'K3', 4, 17, 'Kịch bản nào là một ví dụ về cộng tác kỹ thuật số?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q18', 'tih', 'K3', 4, 18, 'Hình ảnh này cho biết loại thiết bị máy tính nào?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q19', 'tih', 'K3', 4, 19, 'Nhi thích đọc các bài báo trực tuyến. Cô ấy chỉ muốn đọc các bài báo dựa trên sự thật. Câu hỏi nào có thể giúp Nhi xác định các bài báo dựa trên thực tế?', 'single', 'Picture24', TRUE),
  ('tih__k3__mt4__q20', 'tih', 'K3', 4, 20, 'Nhóm nào thích hợp cho bạn bè trực tuyến?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q21', 'tih', 'K3', 4, 21, 'Khi nào thì có thể nói chuyện với người lạ trực tuyến?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q22', 'tih', 'K3', 4, 22, 'Đối với mỗi hành động, hãy chọn Có nếu đó là ví dụ về định dạng văn bản hoặc Không nếu không.', 'matching', NULL, FALSE),
  ('tih__k3__mt4__q23', 'tih', 'K3', 4, 23, 'Đối với mỗi mật khẩu, hãy chọn Mạnh nếu mật khẩu mạnh hoặc Yếu nếu mật khẩu yếu.', 'matching', NULL, FALSE),
  ('tih__k3__mt4__q24', 'tih', 'K3', 4, 24, 'Bạn thấy những bình luận ác ý trong một cuộc trò chuyện trong nhóm trực tuyến. Là một công dân tốt của thời đại kỹ nguyên số, bạn nên nói gì?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q25', 'tih', 'K3', 4, 25, 'Em hãy cho biết, cần sử dụng phần mềm ứng dụng nào để tạo ra các chữ cái tiêu chuẩn thay vì sử dụng máy đánh chữ?', 'single', 'Picture7', TRUE),
  ('tih__k3__mt4__q26', 'tih', 'K3', 4, 26, 'Nhi đang gặp bạn mình sau giờ học để học nhóm. Vào cuối giờ học, giáo viên của Nhi yêu cầu bạn ấy ở lại vài phút để giúp dọn dẹp bàn học. Nhi sẽ đến muộn để gặp bạn mình. Cách nhanh nhất để Nhi nói với bạn mình rằng bạn ấy sẽ đến muộn vài phút là gì?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q27', 'tih', 'K3', 4, 27, 'Hầu hết các thư và email đều có lời chào và lời kết thúc đi. Chọn từng cụm từ từ danh sách bên phải sang đúng thể loại bên trái.', 'matching', NULL, FALSE),
  ('tih__k3__mt4__q28', 'tih', 'K3', 4, 28, 'Thông tin cá nhân nào bạn KHÔNG nên chia sẻ trực tuyến?', 'single', NULL, FALSE),
  ('tih__k3__mt4__q29', 'tih', 'K3', 4, 29, 'Bạn muốn tìm một trò chơi được cài đặt trên máy tính của mình. Trên thanh tác vụ được hiển thị, bạn nên nhấp vào đâu để tìm trò chơi? (Chọn phần tử đúng trong khu vực trả lời.)', 'single', 'Picture1', TRUE),
  ('tih__k3__mt4__q30', 'tih', 'K3', 4, 30, 'Bạn đang tìm kiếm một nơi để đi với các bạn cùng lớp. Bạn đọc một bài đánh giá trực tuyến cho một nhà hàng. Đối với mỗi tuyên bố, hãy chọn Thực tế hoặc Quan điểm.', 'truefalse', NULL, FALSE),
  ('tih__k3__mt4__q31', 'tih', 'K3', 4, 31, 'Nhi đã xây dựng một mô hình lớp học như bài tập về nhà. Bạn ấy muốn đưa nó cho anh của bạn ấy, người sống ở xa. Bạn ấy muốn chỉ cho anh ấy nơi bạn ấy ngồi và nói với anh ấy về giáo viên của bạn ấy và bạn bè của mình. Nhi nên thể hiện và nói với anh mình những điều này như thế nào?', 'single', NULL, FALSE),
