  ('tih__k4__mt3__q12', 'tih', 'K4', 3, 12, 'Tùy chọn nào dưới đây là thuật ngữ chỉ thông tin đầu ra, chẳng hạn như thông tin, âm thanh và hình ảnh?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q13', 'tih', 'K4', 3, 13, 'Tùy chọn nào dưới đây là một ví dụ về bắt nạt mạng (cyberbullying)?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q14', 'tih', 'K4', 3, 14, 'Bạn chạy xong một lượt tìm kiếm trên web, nhưng không tìm được kết quả mình cần. Bạn nên thực hiện 2 bước nào để giúp tinh chỉnh phạm vi tìm kiếm? (Chọn 2)', 'multi', NULL, FALSE),
  ('tih__k4__mt3__q15', 'tih', 'K4', 3, 15, 'Chọn ra hai câu trả lời thể hiện những thông tin thuộc dấu chân kỹ thuật số. (Chọn 2)', 'multi', NULL, FALSE),
  ('tih__k4__mt3__q16', 'tih', 'K4', 3, 16, 'Chọn ba thiết bị đầu ra (Output Device). (Chọn 3)', 'multi', NULL, FALSE),
  ('tih__k4__mt3__q17', 'tih', 'K4', 3, 17, 'Với mỗi câu phát biểu về việc tinh chỉnh phạm vi tìm kiếm trên web, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('tih__k4__mt3__q18', 'tih', 'K4', 3, 18, 'Đâu là định nghĩa cho hành động "Duyệt" (Browsing)?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q19', 'tih', 'K4', 3, 19, 'Bạn đang đọc một bài viết trên trang web. Bên dưới bài viết đó có nhiều đường liên kết cung cấp thêm thông tin ngoài. Bạn nên bấm vào liên kết nào để tìm hiểu về người viết bài báo?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q20', 'tih', 'K4', 3, 20, 'Khi bắt đầu làm dự án nghiên cứu, giáo viên đưa cho bạn ___ để sử dụng. Thứ mà giáo viên đưa cho bạn là gì?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q21', 'tih', 'K4', 3, 21, 'Bạn muốn mua một vật phẩm mới cho trò chơi trực tuyến yêu thích của mình và vật phẩm đó sẽ được khuyến mãi trong 5 phút nữa. Bạn đã mở sẵn trang đó ra. Khi hết 5 phút đó, bạn nên làm gì để nhanh chóng hiển thị mức giá mới?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q22', 'tih', 'K4', 3, 22, 'Bluetooth là gì?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q23', 'tih', 'K4', 3, 23, 'Phản ứng thích hợp nếu bạn bị bắt nạt trên mạng (cyberbullying) là gì?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q24', 'tih', 'K4', 3, 24, 'Đâu là URL đúng của trang CoolPlaces.com?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q25', 'tih', 'K4', 3, 25, 'Phần nào dưới đây của máy tính và được dùng để điều hành máy tính?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q26', 'tih', 'K4', 3, 26, 'Giáo viên cung cấp cho bạn ví dụ về các hành vi xã hội giao kém trên mạng. Hãy di chuyển từng hướng dẫn thực hành phép xã giao trực tuyến từ danh sách bên phải sang ví dụ tương ứng bên trái. (Matching)', 'matching', NULL, FALSE),
  ('tih__k4__mt3__q27', 'tih', 'K4', 3, 27, 'Có thể dùng loại kết nối nào để kết nối tai nghe không dây với máy tính xách tay?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q28', 'tih', 'K4', 3, 28, 'Bạn được bạn của mình giới thiệu một trang web mới cho phép xem phim/video giải trí. Đó là loại trang web gì?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q29', 'tih', 'K4', 3, 29, 'Với mỗi câu phát biểu, hãy chọn Đúng hoặc Sai về dấu chân kỹ thuật số.', 'truefalse', NULL, FALSE),
  ('tih__k4__mt3__q30', 'tih', 'K4', 3, 30, 'Khi bạn sử dụng từ đồng nghĩa để làm rõ mục tiêu tìm kiếm, bạn đang làm gì?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q31', 'tih', 'K4', 3, 31, 'Cách nhanh nhất để quay lại một trang web sau đó là gì?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q32', 'tih', 'K4', 3, 32, 'Thiết bị vật lý nào có vai trò cho hệ điều hành, phần mềm và phần cứng?', 'single', NULL, FALSE),
  ('tih__k4__mt3__q33', 'tih', 'K4', 3, 33, 'Hãy di chuyển từng thuật ngữ từ danh sách bên phải sang định nghĩa tương ứng bên trái. (Matching – trình duyệt)', 'matching', NULL, FALSE),
  ('tih__k4__mt3__q34', 'tih', 'K4', 3, 34, 'Với mỗi câu phát biểu về cáp và kết nối không dây, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
