  ('tih__k4__mt4__q1', 'tih', 'K4', 4, 1, 'Bạn đặt mua một game mới, nhưng khi nhận được thì phát hiện rằng đó là một bản sao chép trái phép. Là một công dân tốt trên môi trường số, bạn nên làm gì?', 'single', NULL, FALSE),
  ('tih__k4__mt4__q2', 'tih', 'K4', 4, 2, 'Với mỗi câu phát biểu về tính an toàn của nội dung kỹ thuật số, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
