  ('tih__k4__mt4__q5', 'tih', 'K4', 4, 5, 'Với mỗi câu phát biểu, hãy chọn Có nếu đó là ví dụ về bắt nạt trên mạng hoặc Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('tih__k4__mt4__q6', 'tih', 'K4', 4, 6, 'Như thế nào là cách giao tiếp thích hợp trên môi trường kỹ thuật số?', 'single', NULL, FALSE),
