  ('tih__k4__mt4__q14', 'tih', 'K4', 4, 14, 'Hãy di chuyển từng ví dụ về nội dung trực tuyến từ danh sách bên phải sang mục đích tương ứng bên trái. (Matching)', 'matching', NULL, FALSE),
  ('tih__k4__mt4__q15', 'tih', 'K4', 4, 15, 'Có thể dùng loại kết nối nào để kết nối tai nghe không dây với máy tính xách tay?', 'single', NULL, FALSE),
