  ('tih__k4__mt4__q17', 'tih', 'K4', 4, 17, 'Bình luận phản hồi nào sau đây là thích hợp? (Scenario)', 'single', NULL, FALSE),
  ('tih__k4__mt4__q18', 'tih', 'K4', 4, 18, 'Với mỗi câu phát biểu về việc giao tiếp kỹ thuật số, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('tih__k4__mt4__q19', 'tih', 'K4', 4, 19, 'Tại sao phải cẩn thận với những gì được đăng trên Internet?', 'single', NULL, FALSE),
  ('tih__k4__mt4__q20', 'tih', 'K4', 4, 20, 'Phần nào dưới đây của máy tính và được dùng để điều hành máy tính?', 'single', NULL, FALSE),
