  ('tih__k4__mt4__q26', 'tih', 'K4', 4, 26, 'Bạn muốn mua một vật phẩm mới cho trò chơi trực tuyến yêu thích của mình và vật phẩm đó sẽ được khuyến mãi trong 5 phút nữa. Khi hết 5 phút đó, bạn nên làm gì để nhanh chóng hiển thị mức giá mới?', 'single', NULL, FALSE),
  ('tih__k4__mt4__q27', 'tih', 'K4', 4, 27, 'Giáo viên yêu cầu bạn tìm hiểu về rừng nhiệt đới rồi chia sẻ những điều học được với bạn cùng lớp thông qua một bài trình chiếu. Mục đích của bài trình chiếu này là gì?', 'single', NULL, FALSE),
  ('tih__k4__mt4__q28', 'tih', 'K4', 4, 28, 'Hãy di chuyển từng thuật ngữ về tạo nội dung từ danh sách bên phải sang định nghĩa tương ứng bên trái. (Matching)', 'matching', NULL, FALSE),
  ('tih__k4__mt4__q29', 'tih', 'K4', 4, 29, 'Như thế nào gọi là Hack (tấn công xâm nhập)?', 'single', NULL, FALSE),
  ('tih__k4__mt4__q30', 'tih', 'K4', 4, 30, 'Với mỗi câu phát biểu về việc xem màn hình lâu, hãy chọn Đúng hoặc Sai (sức khỏe).', 'truefalse', NULL, FALSE);
INSERT INTO minitest_questions (uid, cat_id, level_id, minitest_num, sort_order, question_text, question_type, image_id, has_image) VALUES
  ('tih__k4__mt4__q31', 'tih', 'K4', 4, 31, 'Câu nào là ví dụ về việc bình duyệt (peer review)?', 'single', NULL, FALSE),
  ('tih__k4__mt4__q32', 'tih', 'K4', 4, 32, 'Đâu là một thiết bị nhập (Input Device)?', 'single', NULL, FALSE),
