  ('tih__k4__mt4__q34', 'tih', 'K4', 4, 34, 'Hoàn thành các câu dưới đây bằng cách điền đúng thuật ngữ vào chỗ trống. (Fill-in – trình duyệt)', 'matching', NULL, FALSE),
  ('tih__k4__mt4__q35', 'tih', 'K4', 4, 35, 'Với mỗi câu phát biểu về nội dung kỹ thuật số không an toàn, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('tih__k4__mt4__q36', 'tih', 'K4', 4, 36, 'Câu hỏi này có hình ảnh — vui lòng xem đề thi in để trả lời.', 'single', NULL, FALSE),
  ('tih__k5__mt1__q1', 'tih', 'K5', 1, 1, 'Hãy ghép từng ví dụ giao tiếp với mục đích phù hợp: Học tập hay Giải trí?', 'matching', NULL, FALSE),
  ('tih__k5__mt1__q2', 'tih', 'K5', 1, 2, 'Em đã tạo một blog cho lớp, cho phép các bạn khác đăng ảnh lên. Với mỗi tình huống dưới đây, hãy chọn ''Có'' nếu việc đăng ảnh đó cần được phép hoặc chọn ''Không'' nếu không cần.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q3', 'tih', 'K5', 1, 3, 'Nếu 2 người bạn muốn cùng làm bài tập thì phải làm thế nào?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q4', 'tih', 'K5', 1, 4, 'Ken và Orson đều đang ở nhà. Họ có thể làm bài tập về nhà cùng nhau và cùng lúc qua hình thức kỹ thuật số nào?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q5', 'tih', 'K5', 1, 5, 'Đối với các phát biểu về chia sẻ dữ liệu, Chọn Có nếu đó là vi phạm, ngược lại chọn Không.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q6', 'tih', 'K5', 1, 6, 'Rian vừa đăng Video trực tiếp khi đang đi du lịch với gia đình. Bài đăng nêu cả địa điểm và số ngày đi chơi của cả gia đình. Với mỗi câu phát biểu về bài đăng, hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q7', 'tih', 'K5', 1, 7, 'Em đang dự một hội thảo video trực tiếp. Hội thảo cho phép Em gửi tin nhắn, bật camera và nói chuyện qua micro. Em không đồng ý với một ý kiến mà diễn giả đang nói. Em nên làm gì?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q8', 'tih', 'K5', 1, 8, 'Em hãy cho biết, biểu tượng cảm xúc (Emoji) phù hợp với loại giao tiếp kỹ thuật số nào?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q9', 'tih', 'K5', 1, 9, 'Trong email gửi đến công ty nhờ hỗ trợ dự án trường, dòng Chủ đề (Subject) phù hợp nhất là gì?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q10', 'tih', 'K5', 1, 10, 'Em hãy cho biết, Hacker mũ trắng là gì?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q11', 'tih', 'K5', 1, 11, 'Em nên làm gì nếu nhận được tin nhắn không phù hợp hoặc không an toàn khi trực tuyến?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q12', 'tih', 'K5', 1, 12, 'Em hãy cho biết, mục đích của việc đưa chủ đề vào Email là gì?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q13', 'tih', 'K5', 1, 13, 'Trường nào trong email chứa địa chỉ của người gửi?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q14', 'tih', 'K5', 1, 14, 'Em hãy cho biết, làm thế nào có thể xác định thông tin trên một trang Web có chính xác và đáng tin cậy hay không?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q15', 'tih', 'K5', 1, 15, 'Ghép từng kiểu hợp tác với ví dụ phù hợp:', 'matching', NULL, FALSE),
  ('tih__k5__mt1__q16', 'tih', 'K5', 1, 16, 'Nối từng ví dụ với khái niệm kỹ thuật số tương ứng:', 'matching', NULL, FALSE),
  ('tih__k5__mt1__q17', 'tih', 'K5', 1, 17, 'Em hãy cho biết, trong trường hợp nào em nên xin phép trước khi đăng ảnh của một ai đó lên mạng?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q18', 'tih', 'K5', 1, 18, 'Có người đã đe dọa sẽ gây hại cho em trên một nền tảng mạng xã hội. Em nên làm gì?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q19', 'tih', 'K5', 1, 19, 'Em hãy cho biết, vì sao em nên ý thức về những phát biểu mình đăng trên mạng xã hội?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q20', 'tih', 'K5', 1, 20, 'Em cần thực hiện bước đầu tiên để đảm bảo rằng dấu chân kỹ thuật số (Digital Footprint) của em được tích cực. Em nên làm gì?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q21', 'tih', 'K5', 1, 21, 'Em hãy cho biết, lựa chọn nào là hành động hợp lý khi sử dụng thiết bị điện tử?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q22', 'tih', 'K5', 1, 22, 'Em hãy cho biết, tùy chọn nào sau đây là lợi ích khi cộng tác với người khác? (Chọn 2)', 'multi', NULL, FALSE),
  ('tih__k5__mt1__q23', 'tih', 'K5', 1, 23, 'Em đang học trực tuyến qua ứng dụng video. Ứng dụng cho phép em gửi tin nhắn, bật camera và micro. Trong buổi học, em muốn cho giáo viên biết rằng mình đang chú ý nghe giảng. Em nên làm gì?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q24', 'tih', 'K5', 1, 24, 'Với mỗi câu phát biểu về tác động tiêu cực của bắt nạt trực tuyến (Cyberbullying), em hãy chọn Đúng hoặc Sai.', 'truefalse', NULL, FALSE),
