  ('tih__k5__mt1__q26', 'tih', 'K5', 1, 26, 'Em hãy cho biết, Catfishing là gì?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q27', 'tih', 'K5', 1, 27, 'Em nhận được tin nhắn: ''Laptop đang được giảm giá 40%. Đặt hàng ngay hôm nay để được giao hàng miễn phí. Chúng tôi có đủ mọi cấu hình.'' Với mỗi câu trong tin nhắn này, hãy chọn ''Có'' nếu câu đó có chứa thiên kiến hoặc chọn ''Không'' nếu không có.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q28', 'tih', 'K5', 1, 28, 'Ghép từng thuật ngữ với mô tả tương ứng:', 'matching', NULL, FALSE),
  ('tih__k5__mt1__q29', 'tih', 'K5', 1, 29, 'Hành động nào có các lợi ích tiết kiệm thời gian, quan điểm đa dạng, phân phối theo thế mạnh (sự phân công của) từng người?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q30', 'tih', 'K5', 1, 30, 'Em nhận được tin nhắn: ''Áo khoác đang được giảm giá 40%. Đặt hàng ngay hôm nay để được giao hàng miễn phí. Chúng tôi có đủ mọi kích cỡ.'' Với mỗi câu phát biểu trong tin nhắn này, em hãy chọn Có nếu phát biểu đó có bao gồm thiên kiến hoặc chọn Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q31', 'tih', 'K5', 1, 31, 'Rian muốn cộng tác với một nhóm để làm bài tập của mình. Bạn ấy sẽ nhận được lợi ích gì từ việc này? (Chọn 2)', 'multi', NULL, FALSE),
  ('tih__k5__mt1__q32', 'tih', 'K5', 1, 32, 'Em từng chia sẻ tên tài khoản và mật khẩu của một ứng dụng xem phim với bạn mình. Bây giờ em nhận ra rằng bạn mình có thể xem được lịch sử xem phim của mình. Vậy em nên làm gì để ngăn chặn việc này?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q33', 'tih', 'K5', 1, 33, 'Em đang tạo một biểu đồ thể hiện số điểm mỗi người chơi ghi được so với tổng số điểm đã ghi được trong mùa. Em nên sử dụng loại biểu đồ nào cho dạng so sánh này?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q34', 'tih', 'K5', 1, 34, 'Em hãy cho biết, tùy chọn nào là hành động giúp quản lý dấu chân kỹ thuật số (Digital Footprint) của riêng em?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q35', 'tih', 'K5', 1, 35, 'Bạn nhận được tin nhắn: ''Quần áo đang được giảm giá 50%. Đặt hàng ngay hôm nay để được giao hàng miễn phí. Chúng tôi có đủ mọi kích cỡ.'' Với mỗi câu trong tin nhắn này, hãy chọn ''Có'' nếu câu đó có chứa thiên kiến hoặc chọn ''Không'' nếu không có.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q36', 'tih', 'K5', 1, 36, 'Ghép từng tình huống với thuật ngữ an toàn mạng phù hợp:', 'matching', NULL, FALSE),
  ('tih__k5__mt1__q37', 'tih', 'K5', 1, 37, 'Với mỗi tình huống dưới đây, bạn có cần xin phép người trong ảnh hoặc người giám hộ của họ để đăng ảnh lên mạng xã hội không? Hãy chọn ''Có'' nếu cần xin phép và ''Không'' nếu không cần.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q38', 'tih', 'K5', 1, 38, 'Với mỗi nguồn trên mạng, em hãy chọn Có nếu nguồn đó có thể thu thập dữ liệu của em hoặc chọn Không nếu không thể.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q39', 'tih', 'K5', 1, 39, 'Với mỗi câu phát biểu về việc sử dụng thiết bị, em hãy chọn Đúng nếu đó là một lựa chọn lành mạnh hoặc chọn Sai nếu lựa chọn đó không lành mạnh.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q40', 'tih', 'K5', 1, 40, 'Em hãy chọn ''Có'' nếu đó là lợi ích của việc cộng tác và chọn ''Không'' nếu không phải.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt1__q41', 'tih', 'K5', 1, 41, 'Em và các bạn đang trò chuyện khi chơi game online. Cuộc trò chuyện khiến em cảm thấy khó chịu và lo lắng một người chơi khác đang bị bắt nạt. Em nên làm gì?', 'single', NULL, FALSE),
  ('tih__k5__mt1__q42', 'tih', 'K5', 1, 42, 'Em đã tạo một blog cho lớp, cho phép các bạn khác đăng ảnh lên. Với mỗi bức ảnh sau đây, hãy chọn ''Có'' nếu cần xin phép trước khi đăng hoặc ''Không'' nếu không cần.', 'truefalse', NULL, FALSE),
