  ('tih__k5__mt3__q16', 'tih', 'K5', 3, 16, 'Với mỗi câu phát biểu, em hãy chọn ''Có'' nếu nguồn đó đáng tin cậy hoặc chọn ''Không'' nếu không phải.', 'truefalse', NULL, FALSE),
