  ('tih__k5__mt3__q29', 'tih', 'K5', 3, 29, 'Với mỗi tình huống dưới đây, hãy chọn ''Có'' nếu cần xin phép trước khi đăng ảnh lên mạng xã hội, hoặc chọn ''Không'' nếu không cần.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt3__q30', 'tih', 'K5', 3, 30, 'Em nhận ra rằng mình đã đăng thông tin không phù hợp hoặc chia sẻ quá mức trên mạng. Em nên làm gì trước tiên?', 'single', NULL, FALSE),
  ('tih__k5__mt3__q31', 'tih', 'K5', 3, 31, 'Em hãy cho biết, thuật ngữ nào chỉ các bit dữ liệu nhỏ được thu thập bởi trang Web mà em truy cập?', 'single', NULL, FALSE),
  ('tih__k5__mt3__q32', 'tih', 'K5', 3, 32, 'Em hãy chọn Có nếu câu phát biểu là ví dụ về công dân số mẫu mực hoặc chọn Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt3__q33', 'tih', 'K5', 3, 33, 'Với mỗi câu phát biểu về việc thu thập dữ liệu, em hãy chọn Có nếu nguồn đó thu thập dữ liệu về hoạt động sử dụng của em hoặc chọn Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt3__q34', 'tih', 'K5', 3, 34, 'Em nhận được Email: ''Orson đang tranh cử cho chức chủ tịch của câu lạc bộ khoa học. Tớ biết bạn ấy ghét khoa học vì bạn ấy chẳng bao giờ tham gia hội chợ khoa học nào cả. Bạn ấy nhận được một điểm B ở bài kiểm tra tuần trước.'' Với mỗi câu phát biểu trích từ Email này, em hãy chọn Có nếu phát biểu đó có bao gồm thiên kiến hoặc Không nếu không phải.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt3__q35', 'tih', 'K5', 3, 35, 'Em hãy cho biết, phương tiện nào được sử dụng để bảo vệ sách, phim, trò chơi điện tử và hình ảnh?', 'single', NULL, FALSE),
