  ('tih__k5__mt3__q39', 'tih', 'K5', 3, 39, 'Với mỗi câu phát biểu, em hãy chọn ''Có'' nếu nguồn đó đáng tin cậy hoặc chọn ''Không'' nếu không phải.', 'truefalse', NULL, FALSE),
  ('tih__k5__mt3__q40', 'tih', 'K5', 3, 40, 'Ghép từng trường hợp sử dụng với loại lưu trữ dữ liệu phù hợp:', 'matching', NULL, FALSE),
  ('tih__k5__mt3__q41', 'tih', 'K5', 3, 41, 'Em đọc được bài đăng sau trên mạng xã hội: ''Biến đổi khí hậu chắc chắn là không có thật vì Orson bỏ phiếu chống lại chuyện đó. Mùa hè năm nay mát hơn mùa hè năm ngoái. Hầu hết những người tin vào biến đổi khí hậu là những người đưa ra thuyết âm mưu.'' Với mỗi câu phát biểu trong bài đăng trên mạng xã hội này, hãy chọn Có nếu phát biểu đó có bao gồm thiên kiến hoặc Không nếu không phải.', 'truefalse', NULL, FALSE),
